fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut config = Config::default();
    let mut i = 1;

    if args.len() == 1 {
        return Err("no_input".to_string());
    }

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" => {
                print_help_short();
                process::exit(0);
            }
            "--help" => {
                print_help_long();
                process::exit(0);
            }
            "-V" | "--version" => {
                print_version();
                process::exit(0);
            }
            "--version-long" => {
                print_build_info();
                process::exit(0);
            }
            "-v" | "--verbose" => {
                config.verbose = true;
            }
            "--pretty-json" => {
                config.pretty_json = true;
            }
            "--pretty-json-err" => {
                config.pretty_json_err = true;
            }
            "--no-warnings" => {
                config.no_warnings = true;
            }
            "-j" | "--threads" | "--jobs" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.threads = args[i].parse().map_err(|_| format!("invalid threads value"))?;
            }
            "--evm-version" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                let valid = ["homestead", "tangerineWhistle", "spuriousDragon", "byzantium", 
                            "constantinople", "petersburg", "istanbul", "berlin", "london", 
                            "paris", "shanghai", "cancun", "prague", "osaka"];
                if !valid.contains(&args[i].as_str()) {
                    return Err(format!("invalid evm version: {}", args[i]));
                }
                config.evm_version = args[i].clone();
            }
            "--stop-after" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                let valid = ["parsing", "lowering", "analysis"];
                if !valid.contains(&args[i].as_str()) {
                    return Err(format!("invalid stop-after value: {}", args[i]));
                }
                config.stop_after = Some(args[i].clone());
            }
            "--out-dir" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.out_dir = Some(PathBuf::from(&args[i]));
            }
            "--emit" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.emit = args[i].split(',').map(|s| s.trim().to_string()).collect();
            }
            "--base-path" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.base_path = Some(PathBuf::from(&args[i]));
            }
            "-I" | "--include-path" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.include_paths.push(PathBuf::from(&args[i]));
            }
            "--allow-paths" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.allow_paths.push(args[i].clone());
            }
            "--color" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                let valid = ["auto", "always", "never"];
                if !valid.contains(&args[i].as_str()) {
                    return Err(format!("invalid color value: {}", args[i]));
                }
                config.color = args[i].clone();
            }
            "--error-format" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.error_format = args[i].clone();
            }
            "--error-format-human" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.error_format_human = args[i].clone();
            }
            "--diagnostic-width" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.diagnostic_width = Some(args[i].parse().map_err(|_| "invalid width".to_string())?);
            }
            _ if arg.starts_with("-Z") => {
                let flag = &arg[2..];
                if flag == "help" {
                    print_unstable_help();
                    process::exit(1);
                }
                config.unstable_flags.push(flag.to_string());
            }
            _ if arg.starts_with("--") => {
                // Check for --flag=value form
                if let Some(eq_pos) = arg.find('=') {
                    let flag = &arg[..eq_pos];
                    let value = &arg[eq_pos+1..];
                    // Process as flag=value
                    let mut new_args = args.to_vec();
                    new_args.splice(i..=i, [flag.to_string(), value.to_string()]);
                    return parse_args(&new_args);
                }
                return Err(format!("unknown argument: {}", arg));
            }
            _ if arg.starts_with("-j") && arg.len() > 2 => {
                config.threads = arg[2..].parse().map_err(|_| "invalid threads value".to_string())?;
            }
            _ => {
                // Could be a file, stdin (-), or a remapping (key=value)
                if arg.contains('=') && !arg.starts_with('-') && !arg.starts_with('/') && !arg.starts_with('.') {
                    // It might be a remapping
                    let parts: Vec<&str> = arg.splitn(2, '=').collect();
                    if parts.len() == 2 && !Path::new(arg.as_str()).exists() {
                        config.remappings.push((parts[0].to_string(), parts[1].to_string()));
                    } else {
                        config.inputs.push(arg.clone());
                    }
                } else {
                    config.inputs.push(arg.clone());
                }
            }
        }
        i += 1;
    }

    Ok(config)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let config = match parse_args(&args) {
        Ok(c) => c,
        Err(e) if e == "no_input" => {
            print_help_short();
            process::exit(2);
        }
        Err(e) => {
            eprintln!("error: {}", e);
            process::exit(1);
        }
    };

    let use_color = match config.color.as_str() {
        "always" => true,
        "never" => false,
        _ => {
            // auto: check if stderr is a terminal
            is_terminal()
        }
    };

    let mut compiler = compiler::Compiler::new(config, use_color);
    let exit_code = compiler.run();
    process::exit(exit_code);
}

fn is_terminal() -> bool {
    use std::os::unix::io::AsRawFd;
    let fd = std::io::stderr().as_raw_fd();
    unsafe { libc_isatty(fd) }
}

#[cfg(unix)]
fn libc_isatty(fd: i32) -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) != 0 }
}

#[cfg(not(unix))]
fn libc_isatty(_fd: i32) -> bool {
    false
}

mod compiler {
    use super::*;

    pub struct Compiler {
        config: Config,
        use_color: bool,
    }

    impl Compiler {
        pub fn new(config: Config, use_color: bool) -> Self {
            Compiler { config, use_color }
        }

        pub fn run(&mut self) -> i32 {
            // Collect source files
            let sources = match self.collect_sources() {
                Ok(s) => s,
                Err(e) => {
                    self.emit_error(&e, None, None);
                    return 1;
                }
            };

            if sources.is_empty() {
                return 0;
            }

            // Parse all files
            let mut parse_results = Vec::new();
            let mut had_error = false;

            for (file_name, content) in &sources {
                match crate::parser::parse(file_name, content) {
                    Ok(source_unit) => {
                        parse_results.push((file_name.clone(), content.clone(), source_unit));
                    }
                    Err(errs) => {
                        for err in &errs {
                            self.emit_parse_error(err, file_name, content);
                        }
                        had_error = true;
                    }
                }
            }

            if had_error {
                let count = 1; // simplified
                self.emit_aborting(count);
                return 1;
            }

            if self.config.stop_after.as_deref() == Some("parsing") {
                return 0;
            }

            // Resolve names and analyze
            let mut resolver = crate::resolver::Resolver::new(
                &parse_results,
                &self.config.remappings,
                &self.config.include_paths,
                self.config.base_path.as_deref(),
            );

            // Load imported files
            loop {
                let imports_to_load = resolver.get_pending_imports();
                if imports_to_load.is_empty() {
                    break;
                }

                let mut all_loaded = true;
                for import_path in imports_to_load {
                    match std::fs::read_to_string(&import_path) {
                        Ok(content) => {
                            match crate::parser::parse(&import_path, &content) {
                                Ok(su) => {
                                    resolver.add_source(import_path.clone(), content, su);
                                }
                                Err(errs) => {
                                    for err in &errs {
                                        self.emit_parse_error(err, &import_path, "");
                                    }
                                    had_error = true;
                                    all_loaded = false;
                                }
                            }
                        }
                        Err(e) => {
                            self.emit_error(&format!("cannot open file: {}", e), None, None);
                            had_error = true;
                            all_loaded = false;
                        }
                    }
                }

                if !all_loaded {
                    break;
                }
            }

            if had_error {
                self.emit_aborting(1);
                return 1;
            }

            if self.config.stop_after.as_deref() == Some("lowering") {
                return 0;
            }

            // Run analysis
            let analysis_errors = resolver.analyze();
            let error_count = analysis_errors.iter().filter(|e| e.severity == "error").count();

            if !analysis_errors.is_empty() {
                for err in &analysis_errors {
                    if err.severity == "warning" && self.config.no_warnings {
                        continue;
                    }
                    self.emit_analysis_error(err);
                }

                if error_count > 0 {
                    self.emit_aborting(error_count);
                    return 1;
                }
            }

            if self.config.stop_after.as_deref() == Some("analysis") {
                return 0;
            }

            // Generate output
            if !self.config.emit.is_empty() {
                let output = crate::abi::generate_output(&resolver, &self.config.emit);
                self.write_output(output);
            }

            0
        }

        fn collect_sources(&self) -> Result<Vec<(String, String)>, String> {
            let mut sources = Vec::new();

            for input in &self.config.inputs {
                if input == "-" {
                    // Read from stdin
                    let mut content = String::new();
                    io::stdin().read_to_string(&mut content).map_err(|e| e.to_string())?;
                    sources.push(("<stdin>".to_string(), content));
                } else {
                    // Read from file
                    let content = std::fs::read_to_string(input)
                        .map_err(|e| format!("{}: {}", input, e))?;
                    let file_name = if let Some(base) = &self.config.base_path {
                        // Make relative to base path
                        let path = Path::new(input);
                        if let Ok(rel) = path.strip_prefix(base) {
                            rel.to_string_lossy().to_string()
                        } else {
                            input.clone()
                        }
                    } else {
                        input.clone()
                    };
                    sources.push((file_name, content));
                }
            }

            Ok(sources)
        }

        fn emit_error(&self, msg: &str, file: Option<&str>, pos: Option<(usize, usize)>) {
            match self.config.error_format.as_str() {
                "json" => {
                    let json = format!("{{\"sourceLocation\":null,\"secondarySourceLocations\":[],\"type\":\"Exception\",\"component\":\"general\",\"severity\":\"error\",\"errorCode\":null,\"message\":\"{}\",\"formattedMessage\":\"error: {}\\n\\n\"}}", 
                        escape_json(msg), escape_json(msg));
                    eprintln!("{}", json);
                }
                _ => {
                    if self.use_color {
                        eprintln!("\x1b[1m\x1b[91merror\x1b[0m\x1b[1m: {}\x1b[0m", msg);
                    } else {
                        eprintln!("error: {}", msg);
                    }
                }
            }
        }

        fn emit_aborting(&self, count: usize) {
            let msg = if count == 1 {
                "aborting due to 1 previous error".to_string()
            } else {
                format!("aborting due to {} previous errors", count)
            };

            match self.config.error_format.as_str() {
                "json" => {
                    let formatted = format!("error: {}\\n\\n", escape_json(&msg));
                    let json = format!("{{\"sourceLocation\":null,\"secondarySourceLocations\":[],\"type\":\"Exception\",\"component\":\"general\",\"severity\":\"error\",\"errorCode\":null,\"message\":\"{}\",\"formattedMessage\":\"{}\"}}",
                        escape_json(&msg), formatted);
                    eprintln!("{}", json);
                }
                "rustc-json" => {
                    let formatted = format!("error: {}\\n\\n", escape_json(&msg));
                    let json = format!("{{\"$message_type\":\"diagnostic\",\"message\":\"{}\",\"code\":null,\"level\":\"error\",\"spans\":[],\"children\":[],\"rendered\":\"{}\"}}",
                        escape_json(&msg), formatted);
                    eprintln!("{}", json);
                }
                _ => {
                    if self.use_color {
                        eprintln!("\x1b[1m\x1b[91merror\x1b[0m\x1b[1m: {}\x1b[0m", msg);
                    } else {
                        eprintln!("error: {}", msg);
                    }
                    eprintln!();
                }
            }
        }

        fn emit_parse_error(&self, err: &crate::errors::ParseError, file: &str, content: &str) {
            // Delegate to diagnostics module
            crate::diagnostics::emit_error(
                &err.message,
                Some(file),
                Some(err.span),
                content,
                &self.config.error_format,
                &self.config.error_format_human,
                self.use_color,
                err.note.as_deref(),
                err.code.as_deref(),
                self.config.diagnostic_width,
            );
        }

        fn emit_analysis_error(&self, err: &crate::resolver::AnalysisError) {
            crate::diagnostics::emit_analysis_error(
                err,
                &self.config.error_format,
                &self.config.error_format_human,
                self.use_color,
                self.config.diagnostic_width,
            );
        }

        fn write_output(&self, output: crate::abi::Output) {
            let json_str = if self.config.pretty_json {
                output.to_pretty_json()
            } else {
                output.to_json()
            };

            if let Some(out_dir) = &self.config.out_dir {
                std::fs::create_dir_all(out_dir).unwrap();
                let out_file = out_dir.join("combined.json");
                std::fs::write(out_file, &json_str).unwrap();
            } else {
                println!("{}", json_str);
            }
        }
    }
}

fn escape_json(s: &str) -> String {
    s.replace('\\', "\\\\")
     .replace('"', "\\\"")
     .replace('\n', "\\n")
     .replace('\r', "\\r")
     .replace('\t', "\\t")
}
