fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut config = Config::default();
    let mut i = 1;

    if args.len() == 1 {
        return Err("no_input".to_string());
    }

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" => {
                print_help_short();
                process::exit(0);
            }
            "--help" => {
                print_help_long();
                process::exit(0);
            }
            "-V" | "--version" => {
                print_version();
                process::exit(0);
            }
            "--version-long" => {
                print_build_info();
                process::exit(0);
            }
            "-v" | "--verbose" => {
                config.verbose = true;
            }
            "--pretty-json" => {
                config.pretty_json = true;
            }
            "--pretty-json-err" => {
                config.pretty_json_err = true;
            }
            "--no-warnings" => {
                config.no_warnings = true;
            }
            "-j" | "--threads" | "--jobs" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.threads = args[i].parse().map_err(|_| format!("invalid threads value"))?;
            }
            "--evm-version" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                let valid = ["homestead", "tangerineWhistle", "spuriousDragon", "byzantium", 
                            "constantinople", "petersburg", "istanbul", "berlin", "london", 
                            "paris", "shanghai", "cancun", "prague", "osaka"];
                if !valid.contains(&args[i].as_str()) {
                    return Err(format!("invalid evm version: {}", args[i]));
                }
                config.evm_version = args[i].clone();
            }
            "--stop-after" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                let valid = ["parsing", "lowering", "analysis"];
                if !valid.contains(&args[i].as_str()) {
                    return Err(format!("invalid stop-after value: {}", args[i]));
                }
                config.stop_after = Some(args[i].clone());
            }
            "--out-dir" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.out_dir = Some(PathBuf::from(&args[i]));
            }
            "--emit" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.emit = args[i].split(',').map(|s| s.trim().to_string()).collect();
            }
            "--base-path" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.base_path = Some(PathBuf::from(&args[i]));
            }
            "-I" | "--include-path" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.include_paths.push(PathBuf::from(&args[i]));
            }
            "--allow-paths" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.allow_paths.push(args[i].clone());
            }
            "--color" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                let valid = ["auto", "always", "never"];
                if !valid.contains(&args[i].as_str()) {
                    return Err(format!("invalid color value: {}", args[i]));
                }
                config.color = args[i].clone();
            }
            "--error-format" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.error_format = args[i].clone();
            }
            "--error-format-human" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.error_format_human = args[i].clone();
            }
            "--diagnostic-width" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("argument '{}' requires a value", arg));
                }
                config.diagnostic_width = Some(args[i].parse().map_err(|_| "invalid width".to_string())?);
            }
            _ if arg.starts_with("-Z") => {
                let flag = &arg[2..];
                if flag == "help" {
                    print_unstable_help();
                    process::exit(1);
                }
                config.unstable_flags.push(flag.to_string());
            }
            _ if arg.starts_with("--") => {
                // Check for --flag=value form
                if let Some(eq_pos) = arg.find('=') {
                    let flag = &arg[..eq_pos];
                    let value = &arg[eq_pos+1..];
                    // Process as flag=value
                    let mut new_args = args.to_vec();
                    new_args.splice(i..=i, [flag.to_string(), value.to_string()]);
                    return parse_args(&new_args);
                }
                return Err(format!("unknown argument: {}", arg));
            }
            _ if arg.starts_with("-j") && arg.len() > 2 => {
                config.threads = arg[2..].parse().map_err(|_| "invalid threads value".to_string())?;
            }
            _ => {
                // Could be a file, stdin (-), or a remapping (key=value)
                if arg.contains('=') && !arg.starts_with('-') && !arg.starts_with('/') && !arg.starts_with('.') {
                    // It might be a remapping
                    let parts: Vec<&str> = arg.splitn(2, '=').collect();
                    if parts.len() == 2 && !Path::new(arg.as_str()).exists() {
                        config.remappings.push((parts[0].to_string(), parts[1].to_string()));
                    } else {
                        config.inputs.push(arg.clone());
                    }
                } else {
                    config.inputs.push(arg.clone());
                }
            }
        }
        i += 1;
    }

    Ok(config)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let config = match parse_args(&args) {
        Ok(c) => c,
        Err(e) if e == "no_input" => {
            print_help_short();
            process::exit(2);
        }
        Err(e) => {
            eprintln!("error: {}", e);
            process::exit(1);
        }
    };

    let use_color = match config.color.as_str() {
        "always" => true,
        "never" => false,
        _ => {
            // auto: check if stderr is a terminal
            is_terminal()
        }
    };

    let mut compiler = compiler::Compiler::new(config, use_color);
    let exit_code = compiler.run();
    process::exit(exit_code);
}

fn is_terminal() -> bool {
    use std::os::unix::io::AsRawFd;
    let fd = std::io::stderr().as_raw_fd();
    unsafe { libc_isatty(fd) }
}

#[cfg(unix)]
fn libc_isatty(fd: i32) -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) != 0 }
}

#[cfg(not(unix))]
fn libc_isatty(_fd: i32) -> bool {
