fn is_terminal() -> bool {
    use std::os::unix::io::AsRawFd;
    let fd = std::io::stderr().as_raw_fd();
    unsafe { libc_isatty(fd) }
}

#[cfg(unix)]
fn libc_isatty(fd: i32) -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) != 0 }
}

#[cfg(not(unix))]
fn libc_isatty(_fd: i32) -> bool {
    false
}

mod compiler {
    use super::*;

    pub struct Compiler {
        config: Config,
        use_color: bool,
    }

    impl Compiler {
        pub fn new(config: Config, use_color: bool) -> Self {
            Compiler { config, use_color }
        }

        pub fn run(&mut self) -> i32 {
            // Collect source files
            let sources = match self.collect_sources() {
                Ok(s) => s,
                Err(e) => {
                    self.emit_error(&e, None, None);
                    return 1;
                }
            };

            if sources.is_empty() {
                return 0;
            }

            // Parse all files
            let mut parse_results = Vec::new();
            let mut had_error = false;

            for (file_name, content) in &sources {
                match crate::parser::parse(file_name, content) {
                    Ok(source_unit) => {
                        parse_results.push((file_name.clone(), content.clone(), source_unit));
                    }
                    Err(errs) => {
                        for err in &errs {
                            self.emit_parse_error(err, file_name, content);
                        }
                        had_error = true;
                    }
                }
            }

            if had_error {
                let count = 1; // simplified
                self.emit_aborting(count);
                return 1;
            }

            if self.config.stop_after.as_deref() == Some("parsing") {
                return 0;
            }

            // Resolve names and analyze
            let mut resolver = crate::resolver::Resolver::new(
                &parse_results,
                &self.config.remappings,
                &self.config.include_paths,
                self.config.base_path.as_deref(),
            );

            // Load imported files
            loop {
                let imports_to_load = resolver.get_pending_imports();
                if imports_to_load.is_empty() {
                    break;
                }

                let mut all_loaded = true;
                for import_path in imports_to_load {
                    match std::fs::read_to_string(&import_path) {
                        Ok(content) => {
                            match crate::parser::parse(&import_path, &content) {
                                Ok(su) => {
                                    resolver.add_source(import_path.clone(), content, su);
                                }
                                Err(errs) => {
                                    for err in &errs {
                                        self.emit_parse_error(err, &import_path, "");
                                    }
                                    had_error = true;
                                    all_loaded = false;
                                }
                            }
                        }
                        Err(e) => {
                            self.emit_error(&format!("cannot open file: {}", e), None, None);
                            had_error = true;
                            all_loaded = false;
                        }
                    }
                }

                if !all_loaded {
                    break;
                }
            }

            if had_error {
                self.emit_aborting(1);
                return 1;
            }

            if self.config.stop_after.as_deref() == Some("lowering") {
                return 0;
            }

            // Run analysis
            let analysis_errors = resolver.analyze();
            let error_count = analysis_errors.iter().filter(|e| e.severity == "error").count();

            if !analysis_errors.is_empty() {
                for err in &analysis_errors {
                    if err.severity == "warning" && self.config.no_warnings {
                        continue;
                    }
                    self.emit_analysis_error(err);
                }

                if error_count > 0 {
                    self.emit_aborting(error_count);
                    return 1;
                }
            }

            if self.config.stop_after.as_deref() == Some("analysis") {
                return 0;
            }

            // Generate output
            if !self.config.emit.is_empty() {
                let output = crate::abi::generate_output(&resolver, &self.config.emit);
                self.write_output(output);
            }

            0
        }

        fn collect_sources(&self) -> Result<Vec<(String, String)>, String> {
            let mut sources = Vec::new();

            for input in &self.config.inputs {
                if input == "-" {
                    // Read from stdin
                    let mut content = String::new();
                    io::stdin().read_to_string(&mut content).map_err(|e| e.to_string())?;
                    sources.push(("<stdin>".to_string(), content));
                } else {
                    // Read from file
                    let content = std::fs::read_to_string(input)
                        .map_err(|e| format!("{}: {}", input, e))?;
                    let file_name = if let Some(base) = &self.config.base_path {
                        // Make relative to base path
                        let path = Path::new(input);
                        if let Ok(rel) = path.strip_prefix(base) {
                            rel.to_string_lossy().to_string()
                        } else {
                            input.clone()
                        }
                    } else {
                        input.clone()
                    };
                    sources.push((file_name, content));
                }
            }

            Ok(sources)
        }

        fn emit_error(&self, msg: &str, file: Option<&str>, pos: Option<(usize, usize)>) {
            match self.config.error_format.as_str() {
                "json" => {
                    let json = format!("{{\"sourceLocation\":null,\"secondarySourceLocations\":[],\"type\":\"Exception\",\"component\":\"general\",\"severity\":\"error\",\"errorCode\":null,\"message\":\"{}\",\"formattedMessage\":\"error: {}\\n\\n\"}}", 
                        escape_json(msg), escape_json(msg));
                    eprintln!("{}", json);
                }
                _ => {
                    if self.use_color {
                        eprintln!("\x1b[1m\x1b[91merror\x1b[0m\x1b[1m: {}\x1b[0m", msg);
                    } else {
                        eprintln!("error: {}", msg);
                    }
                }
            }
        }

        fn emit_aborting(&self, count: usize) {
            let msg = if count == 1 {
                "aborting due to 1 previous error".to_string()
            } else {
                format!("aborting due to {} previous errors", count)
            };

            match self.config.error_format.as_str() {
                "json" => {
                    let formatted = format!("error: {}\\n\\n", escape_json(&msg));
                    let json = format!("{{\"sourceLocation\":null,\"secondarySourceLocations\":[],\"type\":\"Exception\",\"component\":\"general\",\"severity\":\"error\",\"errorCode\":null,\"message\":\"{}\",\"formattedMessage\":\"{}\"}}",
                        escape_json(&msg), formatted);
                    eprintln!("{}", json);
                }
                "rustc-json" => {
                    let formatted = format!("error: {}\\n\\n", escape_json(&msg));
                    let json = format!("{{\"$message_type\":\"diagnostic\",\"message\":\"{}\",\"code\":null,\"level\":\"error\",\"spans\":[],\"children\":[],\"rendered\":\"{}\"}}",
                        escape_json(&msg), formatted);
                    eprintln!("{}", json);
                }
                _ => {
                    if self.use_color {
                        eprintln!("\x1b[1m\x1b[91merror\x1b[0m\x1b[1m: {}\x1b[0m", msg);
                    } else {
                        eprintln!("error: {}", msg);
                    }
                    eprintln!();
                }
            }
        }

        fn emit_parse_error(&self, err: &crate::errors::ParseError, file: &str, content: &str) {
            // Delegate to diagnostics module
            crate::diagnostics::emit_error(
                &err.message,
                Some(file),
                Some(err.span),
                content,
                &self.config.error_format,
                &self.config.error_format_human,
                self.use_color,
                err.note.as_deref(),
                err.code.as_deref(),
                self.config.diagnostic_width,
            );
        }

        fn emit_analysis_error(&self, err: &crate::resolver::AnalysisError) {
            crate::diagnostics::emit_analysis_error(
                err,
                &self.config.error_format,
                &self.config.error_format_human,
                self.use_color,
                self.config.diagnostic_width,
            );
        }

        fn write_output(&self, output: crate::abi::Output) {
            let json_str = if self.config.pretty_json {
                output.to_pretty_json()
            } else {
                output.to_json()
            };

            if let Some(out_dir) = &self.config.out_dir {
                std::fs::create_dir_all(out_dir).unwrap();
                let out_file = out_dir.join("combined.json");
                std::fs::write(out_file, &json_str).unwrap();
            } else {
                println!("{}", json_str);
            }
        }
    }
}

fn escape_json(s: &str) -> String {
    s.replace('\\', "\\\\")
     .replace('"', "\\\"")
     .replace('\n', "\\n")
     .replace('\r', "\\r")
     .replace('\t', "\\t")
}
