enum ParseResult {
    Config(Config),
    ShowHelp(bool), // true = long help
    ShowVersion,
    ShowBuildInfo,
    ShowUnstableHelp,
    Error(String),
    NoInput,
}

fn parse_args(args: &[String]) -> ParseResult {
    let mut config = Config::default();
    let mut i = 1;

    if args.len() == 1 {
        return ParseResult::NoInput;
    }

    while i < args.len() {
        let arg = args[i].clone();

        // Check for --flag=value form
        if arg.starts_with("--") && arg.contains('=') {
            let eq_pos = arg.find('=').unwrap();
            let flag = arg[..eq_pos].to_string();
            let value = arg[eq_pos+1..].to_string();
            let mut new_args = args.to_vec();
            new_args.splice(i..=i, [flag, value]);
            return parse_args(&new_args);
        }

        match arg.as_str() {
            "-h" => return ParseResult::ShowHelp(false),
            "--help" => return ParseResult::ShowHelp(true),
            "-V" | "--version" => return ParseResult::ShowVersion,
            "--version-long" => return ParseResult::ShowBuildInfo,
            "-v" | "--verbose" => {
                config.verbose = true;
            }
            "--pretty-json" => {
                config.pretty_json = true;
            }
            "--pretty-json-err" => {
                config.pretty_json_err = true;
            }
            "--no-warnings" => {
                config.no_warnings = true;
            }
            "-j" | "--threads" | "--jobs" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                match args[i].parse::<usize>() {
                    Ok(n) => config.threads = n,
                    Err(_) => return ParseResult::Error("invalid threads value".to_string()),
                }
            }
            "--evm-version" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.evm_version = args[i].clone();
            }
            "--stop-after" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.stop_after = Some(args[i].clone());
            }
            "--out-dir" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.out_dir = Some(PathBuf::from(&args[i]));
            }
            "--emit" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.emit = args[i].split(',').map(|s| s.trim().to_string()).collect();
            }
            "--base-path" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.base_path = Some(PathBuf::from(&args[i]));
            }
            "-I" | "--include-path" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.include_paths.push(PathBuf::from(&args[i]));
            }
            "--allow-paths" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.allow_paths.push(args[i].clone());
