                match args[i].parse::<usize>() {
                    Ok(n) => config.diagnostic_width = Some(n),
                    Err(_) => return ParseResult::Error("invalid width".to_string()),
                }
            }
            _ if arg.starts_with("-Z") => {
                let flag = &arg[2..];
                if flag == "help" {
                    return ParseResult::ShowUnstableHelp;
                }
                config.unstable_flags.push(flag.to_string());
            }
            _ if arg.starts_with("-j") && arg.len() > 2 => {
                match arg[2..].parse::<usize>() {
                    Ok(n) => config.threads = n,
                    Err(_) => return ParseResult::Error("invalid threads value".to_string()),
                }
            }
            _ => {
                // Could be a file, stdin (-), or a remapping (key=value)
                // Remappings look like "prefix=path" and don't start with / or .
                let is_remapping = arg.contains('=') 
                    && !arg.starts_with('-')
                    && !arg.starts_with('/')
                    && !arg.starts_with('.')
                    && !Path::new(&arg).exists();

