enum ParseResult {
    Config(Config),
    ShowHelp(bool), // true = long help
    ShowVersion,
    ShowBuildInfo,
    ShowUnstableHelp,
    Error(String),
    NoInput,
}

fn parse_args(args: &[String]) -> ParseResult {
    let mut config = Config::default();
    let mut i = 1;

    if args.len() == 1 {
        return ParseResult::NoInput;
    }

    while i < args.len() {
        let arg = args[i].clone();

        // Check for --flag=value form
        if arg.starts_with("--") && arg.contains('=') {
            let eq_pos = arg.find('=').unwrap();
            let flag = arg[..eq_pos].to_string();
            let value = arg[eq_pos+1..].to_string();
            let mut new_args = args.to_vec();
            new_args.splice(i..=i, [flag, value]);
            return parse_args(&new_args);
        }

        match arg.as_str() {
            "-h" => return ParseResult::ShowHelp(false),
            "--help" => return ParseResult::ShowHelp(true),
            "-V" | "--version" => return ParseResult::ShowVersion,
            "--version-long" => return ParseResult::ShowBuildInfo,
            "-v" | "--verbose" => {
                config.verbose = true;
            }
            "--pretty-json" => {
                config.pretty_json = true;
            }
            "--pretty-json-err" => {
                config.pretty_json_err = true;
            }
            "--no-warnings" => {
                config.no_warnings = true;
            }
            "-j" | "--threads" | "--jobs" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                match args[i].parse::<usize>() {
                    Ok(n) => config.threads = n,
                    Err(_) => return ParseResult::Error("invalid threads value".to_string()),
                }
            }
            "--evm-version" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.evm_version = args[i].clone();
            }
            "--stop-after" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.stop_after = Some(args[i].clone());
            }
            "--out-dir" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.out_dir = Some(PathBuf::from(&args[i]));
            }
            "--emit" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.emit = args[i].split(',').map(|s| s.trim().to_string()).collect();
            }
            "--base-path" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.base_path = Some(PathBuf::from(&args[i]));
            }
            "-I" | "--include-path" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.include_paths.push(PathBuf::from(&args[i]));
            }
            "--allow-paths" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.allow_paths.push(args[i].clone());
            }
            "--color" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.color = args[i].clone();
            }
            "--error-format" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.error_format = args[i].clone();
            }
            "--error-format-human" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                config.error_format_human = args[i].clone();
            }
            "--diagnostic-width" => {
                i += 1;
                if i >= args.len() {
                    return ParseResult::Error(format!("argument '{}' requires a value", arg));
                }
                match args[i].parse::<usize>() {
                    Ok(n) => config.diagnostic_width = Some(n),
                    Err(_) => return ParseResult::Error("invalid width".to_string()),
                }
            }
            _ if arg.starts_with("-Z") => {
                let flag = &arg[2..];
                if flag == "help" {
                    return ParseResult::ShowUnstableHelp;
                }
                config.unstable_flags.push(flag.to_string());
            }
            _ if arg.starts_with("-j") && arg.len() > 2 => {
                match arg[2..].parse::<usize>() {
                    Ok(n) => config.threads = n,
                    Err(_) => return ParseResult::Error("invalid threads value".to_string()),
                }
            }
            _ => {
                // Could be a file, stdin (-), or a remapping (key=value)
                // Remappings look like "prefix=path" and don't start with / or .
                let is_remapping = arg.contains('=') 
                    && !arg.starts_with('-')
                    && !arg.starts_with('/')
                    && !arg.starts_with('.')
                    && !Path::new(&arg).exists();

                if is_remapping {
                    if let Some(eq_pos) = arg.find('=') {
                        let key = arg[..eq_pos].to_string();
                        let val = arg[eq_pos+1..].to_string();
                        config.remappings.push((key, val));
                    } else {
                        config.inputs.push(arg);
                    }
                } else {
                    config.inputs.push(arg);
                }
            }
        }
        i += 1;
    }

    ParseResult::Config(config)
}

fn is_terminal() -> bool {
    extern "C" { fn isatty(fd: i32) -> i32; }
    unsafe { isatty(2) != 0 }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    match parse_args(&args) {
        ParseResult::ShowHelp(long) => {
            if long {
                print_help_long();
            } else {
                print_help_short();
            }
            process::exit(0);
        }
        ParseResult::ShowVersion => {
            print_version();
            process::exit(0);
        }
        ParseResult::ShowBuildInfo => {
            print_build_info();
            process::exit(0);
        }
        ParseResult::ShowUnstableHelp => {
            print_unstable_help();
            process::exit(1);
        }
        ParseResult::NoInput => {
            print_help_short();
            process::exit(2);
        }
        ParseResult::Error(e) => {
            eprintln!("error: {}", e);
            process::exit(1);
        }
        ParseResult::Config(config) => {
            let use_color = match config.color.as_str() {
                "always" => true,
                "never" => false,
                _ => is_terminal(),
            };

            let exit_code = run_compiler(config, use_color);
            process::exit(exit_code);
        }
    }
}

fn run_compiler(config: Config, use_color: bool) -> i32 {
    // Collect source files
    let sources = match collect_sources(&config) {
        Ok(s) => s,
        Err(e) => {
            diagnostics::emit_simple_error(&e, &config.error_format, use_color);
            return 1;
        }
    };

    if sources.is_empty() {
        return 0;
    }

    // Parse all files
    let mut parsed_sources: Vec<(String, String, ast::SourceUnit)> = Vec::new();
    let mut error_count = 0usize;

    for (file_name, content) in &sources {
        match parser::parse(file_name, content) {
            Ok(source_unit) => {
                parsed_sources.push((file_name.clone(), content.clone(), source_unit));
            }
            Err(errs) => {
                for err in &errs {
                    diagnostics::emit_parse_error(
                        err,
                        file_name,
                        content,
                        &config.error_format,
                        &config.error_format_human,
                        use_color,
                        config.diagnostic_width,
                    );
                    error_count += 1;
                }
            }
        }
    }

    if error_count > 0 {
        diagnostics::emit_aborting(error_count, &config.error_format, use_color);
        return 1;
    }

    if config.stop_after.as_deref() == Some("parsing") {
        return 0;
    }

    // Resolve imports
    let no_resolve = config.unstable_flags.iter().any(|f| f == "no-resolve-imports");

    let mut all_sources = parsed_sources.clone();

    if !no_resolve {
        let mut loaded_files: std::collections::HashSet<String> = sources.iter().map(|(n, _)| n.clone()).collect();
        let mut pending: Vec<String> = Vec::new();

        // Collect initial imports
        for (file_name, _content, su) in &parsed_sources {
            for import_path in collect_imports(su) {
                let resolved = resolve_import(&import_path, file_name, &config);
                if let Some(resolved_path) = resolved {
                    if !loaded_files.contains(&resolved_path) {
                        pending.push(resolved_path);
                    }
                }
            }
        }

        while !pending.is_empty() {
            let current_pending = pending.drain(..).collect::<Vec<_>>();
            for import_path in current_pending {
                if loaded_files.contains(&import_path) {
                    continue;
                }
                loaded_files.insert(import_path.clone());

                match std::fs::read_to_string(&import_path) {
                    Ok(content) => {
                        match parser::parse(&import_path, &content) {
                            Ok(su) => {
                                // Collect transitive imports
                                for sub_import in collect_imports(&su) {
                                    let resolved = resolve_import(&sub_import, &import_path, &config);
                                    if let Some(rp) = resolved {
                                        if !loaded_files.contains(&rp) {
                                            pending.push(rp);
                                        }
                                    }
                                }
                                all_sources.push((import_path, content, su));
                            }
                            Err(errs) => {
                                for err in &errs {
                                    diagnostics::emit_parse_error(
                                        err,
                                        &import_path,
                                        "",
                                        &config.error_format,
                                        &config.error_format_human,
                                        use_color,
                                        config.diagnostic_width,
                                    );
                                    error_count += 1;
                                }
                            }
                        }
                    }
                    Err(e) => {
                        let msg = format!("{}: {}", import_path, e);
                        diagnostics::emit_simple_error(&msg, &config.error_format, use_color);
                        error_count += 1;
                    }
                }
            }
        }
    }

    if error_count > 0 {
        diagnostics::emit_aborting(error_count, &config.error_format, use_color);
        return 1;
    }

    if config.stop_after.as_deref() == Some("lowering") {
        return 0;
    }

    // Analysis
    let analysis_errors = resolver::analyze(&all_sources);
    let analysis_error_count = analysis_errors.iter().filter(|e| e.severity == "error").count();

    for err in &analysis_errors {
        if err.severity == "warning" && config.no_warnings {
            continue;
        }
        diagnostics::emit_analysis_error(
            err,
            &config.error_format,
            &config.error_format_human,
            use_color,
            config.diagnostic_width,
        );
    }

    if analysis_error_count > 0 {
        diagnostics::emit_aborting(analysis_error_count, &config.error_format, use_color);
        return 1;
    }

    if config.stop_after.as_deref() == Some("analysis") {
        return 0;
    }

    // Generate output
    if !config.emit.is_empty() {
        let output = abi_gen::generate_output(&all_sources, &config.emit);
        let json_str = if config.pretty_json {
            output.to_pretty_json()
        } else {
            output.to_json()
        };

        if let Some(out_dir) = &config.out_dir {
            let _ = std::fs::create_dir_all(out_dir);
            let out_file = out_dir.join("combined.json");
            let _ = std::fs::write(out_file, &json_str);
        } else {
            println!("{}", json_str);
        }
    }

    0
}

fn collect_sources(config: &Config) -> Result<Vec<(String, String)>, String> {
    let mut sources = Vec::new();

    for input in &config.inputs {
        if input == "-" {
            let mut content = String::new();
            io::stdin().read_to_string(&mut content).map_err(|e| e.to_string())?;
            sources.push(("<stdin>".to_string(), content));
        } else {
            let content = std::fs::read_to_string(input)
                .map_err(|e| format!("{}: {}", input, e))?;
            let file_name = if let Some(base) = &config.base_path {
                let path = Path::new(input);
                if let Ok(rel) = path.strip_prefix(base) {
                    rel.to_string_lossy().to_string()
                } else {
                    input.clone()
                }
            } else {
                input.clone()
            };
            sources.push((file_name, content));
        }
    }

    Ok(sources)
}

fn collect_imports(su: &ast::SourceUnit) -> Vec<String> {
    let mut imports = Vec::new();
    for item in &su.items {
        if let ast::SourceUnitItem::ImportDirective(imp) = item {
            imports.push(imp.path.clone());
        }
    }
    imports
}

fn resolve_import(import_path: &str, from_file: &str, config: &Config) -> Option<String> {
    // Check remappings first
    for (prefix, replacement) in &config.remappings {
        if import_path.starts_with(prefix.as_str()) {
            let rest = &import_path[prefix.len()..];
            let resolved = format!("{}{}", replacement, rest);
            return Some(resolved);
        }
    }

    // If it's an absolute path
    if import_path.starts_with('/') {
        return Some(import_path.to_string());
    }

    // Try base path
    if let Some(base) = &config.base_path {
        let full = base.join(import_path);
        if full.exists() {
            return Some(full.to_string_lossy().to_string());
        }
    }

    // Try include paths
    for inc in &config.include_paths {
        let full = inc.join(import_path);
        if full.exists() {
            return Some(full.to_string_lossy().to_string());
        }
    }

    // Try relative to current file
    if from_file != "<stdin>" {
        let parent = Path::new(from_file).parent().unwrap_or(Path::new("."));
        let full = parent.join(import_path);
        if full.exists() {
            return Some(full.to_string_lossy().to_string());
        }
    }

    None
}
