// Solidity Lexer

use crate::ast::Span;

#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    // Literals
    NumberLiteral(String),
    StringLiteral(String),
    HexLiteral(String),
    BoolLiteral(bool),

    // Identifiers / keywords
    Identifier(String),

    // Keywords
    Pragma,
    Import,
    Contract,
    Library,
    Interface,
    Abstract,
    Is,
    Constructor,
    Function,
    Event,
    Error,
    Struct,
    Enum,
    Mapping,
    Modifier,
    Using,
    For,
    Type,

    // Visibility
    Public,
    Private,
    External,
    Internal,

    // Mutability
    Pure,
    View,
    Payable,

    // Other qualifiers
    Immutable,
    Constant,
    Virtual,
    Override,
    Anonymous,
    Indexed,
    Memory,
    Storage,
    Calldata,

    // Flow
    If,
    Else,
    While,
    Do,
    For_,
    Break,
    Continue,
    Return,
    Emit,
    Revert,
    Delete,
    New,

    // Elementary types
    Address,
    Bool,
    String_,
    Bytes,
    Int(u16),      // int8..int256
    Uint(u16),     // uint8..uint256
    Bytes_(u8),    // bytes1..bytes32
    Fixed,
    Ufixed,

    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    PlusPlus,
    MinusMinus,
    StarStar,

    Eq,
    EqEq,
    BangEq,
    Lt,
    LtEq,
    Gt,
    GtEq,

    And,
    Or,
    Not,
    AndAnd,
    OrOr,

    Tilde,
    Caret,
    LtLt,
    GtGt,

    PlusEq,
    MinusEq,
    StarEq,
    SlashEq,
    PercentEq,

    Question,
    Colon,

    // Punctuation
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Semicolon,
    Comma,
    Dot,
    Arrow,
    FatArrow,
    ColonColon,

    // Special
    Underscore,

    // Others
    Returns,
    Fallback,
    Receive,
    Assembly,
    Unchecked,
    Try,
    Catch,

    // End
    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub span: Span,
    pub text: String,
}

pub struct Lexer<'a> {
    pub source: &'a str,
    pub pos: usize,
}

impl<'a> Lexer<'a> {
    pub fn new(source: &'a str) -> Self {
        Lexer { source, pos: 0 }
    }

    fn current(&self) -> Option<char> {
        self.source[self.pos..].chars().next()
    }

    fn peek(&self, offset: usize) -> Option<char> {
        self.source[self.pos..].chars().nth(offset)
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.current()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn skip_whitespace_and_comments(&mut self) {
        loop {
            // Skip whitespace
            while self.current().map(|c| c.is_whitespace()).unwrap_or(false) {
                self.advance();
            }

            // Check for comments
            if self.current() == Some('/') {
                if self.peek(1) == Some('/') {
                    // Line comment
                    while let Some(c) = self.current() {
                        if c == '\n' { break; }
                        self.advance();
                    }
                } else if self.peek(1) == Some('*') {
                    // Block comment
                    self.advance(); // /
                    self.advance(); // *
                    loop {
                        if self.current() == Some('*') && self.peek(1) == Some('/') {
                            self.advance(); // *
                            self.advance(); // /
                            break;
                        }
                        if self.advance().is_none() {
                            break;
                        }
                    }
                } else {
                    break;
                }
            } else {
                break;
            }
        }
    }

    pub fn next_token(&mut self) -> Token {
        self.skip_whitespace_and_comments();

        let start = self.pos;

        let c = match self.current() {
            None => {
                return Token {
                    kind: TokenKind::Eof,
                    span: Span { start, end: start },
                    text: String::new(),
                };
            }
            Some(c) => c,
        };

        // String literals
        if c == '"' || c == '\'' {
            return self.lex_string(c);
        }

        // Hex literal
        if c == '0' && self.peek(1) == Some('x') {
            return self.lex_hex_number();
        }

        // Number literals
        if c.is_ascii_digit() {
            return self.lex_number();
        }

        // Identifiers and keywords
        if c.is_alphabetic() || c == '_' || c == '$' {
            return self.lex_identifier_or_keyword();
        }

        // Operators and punctuation
        self.advance();
        let end = self.pos;
        let text = self.source[start..end].to_string();

        let kind = match c {
            '(' => TokenKind::LParen,
            ')' => TokenKind::RParen,
            '{' => TokenKind::LBrace,
            '}' => TokenKind::RBrace,
            '[' => TokenKind::LBracket,
            ']' => TokenKind::RBracket,
            ';' => TokenKind::Semicolon,
            ',' => TokenKind::Comma,
            '?' => TokenKind::Question,
            '~' => TokenKind::Tilde,
            '.' => {
                if self.current() == Some('.') && self.peek(1) == Some('.') {
                    self.advance(); self.advance();
                    TokenKind::Identifier("...".to_string()) // spread
                } else {
                    TokenKind::Dot
                }
            }
            ':' => {
                if self.current() == Some(':') {
                    self.advance();
                    TokenKind::ColonColon
                } else {
                    TokenKind::Colon
                }
            }
            '=' => {
                if self.current() == Some('=') {
                    self.advance();
                    TokenKind::EqEq
                } else if self.current() == Some('>') {
                    self.advance();
                    TokenKind::FatArrow
                } else {
                    TokenKind::Eq
                }
            }
            '!' => {
                if self.current() == Some('=') {
                    self.advance();
                    TokenKind::BangEq
                } else {
                    TokenKind::Not
                }
            }
