    if s.starts_with("bytes") && s.len() > 5 {
        let n: u8 = s[5..].parse().ok()?;
        if n >= 1 && n <= 32 {
            return Some(TokenKind::Bytes_(n));
        }
    }
    None
}

pub fn tokenize(source: &str) -> Vec<Token> {
    let mut lexer = Lexer::new(source);
    let mut tokens = Vec::new();
    loop {
        let tok = lexer.next_token();
