                if self.current() == Some('-') {
                    self.advance();
                    TokenKind::MinusMinus
                } else if self.current() == Some('=') {
                    self.advance();
                    TokenKind::MinusEq
                } else if self.current() == Some('>') {
                    self.advance();
                    TokenKind::Arrow
                } else {
                    TokenKind::Minus
                }
            }
            '*' => {
                if self.current() == Some('*') {
                    self.advance();
                    TokenKind::StarStar
                } else if self.current() == Some('=') {
                    self.advance();
                    TokenKind::StarEq
                } else {
                    TokenKind::Star
                }
            }
            '/' => {
                if self.current() == Some('=') {
                    self.advance();
                    TokenKind::SlashEq
                } else {
                    TokenKind::Slash
                }
            }
            '%' => {
                if self.current() == Some('=') {
                    self.advance();
                    TokenKind::PercentEq
                } else {
                    TokenKind::Percent
                }
            }
            '&' => {
                if self.current() == Some('&') {
                    self.advance();
                    TokenKind::AndAnd
                } else {
                    TokenKind::And
                }
            }
            '|' => {
                if self.current() == Some('|') {
                    self.advance();
                    TokenKind::OrOr
                } else {
                    TokenKind::Or
                }
            }
            '^' => TokenKind::Caret,
            _ => TokenKind::Identifier(text.clone()),
        };

        Token {
            kind,
            span: Span { start, end: self.pos },
            text: self.source[start..self.pos].to_string(),
        }
    }

    fn lex_string(&mut self, quote: char) -> Token {
        let start = self.pos;
        self.advance(); // opening quote
        let mut s = String::new();
        loop {
            match self.current() {
                None | Some('\n') => break,
                Some('\\') => {
                    self.advance();
                    match self.advance() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('\\') => s.push('\\'),
                        Some('"') => s.push('"'),
                        Some('\'') => s.push('\''),
                        Some('0') => s.push('\0'),
                        Some(c) => { s.push('\\'); s.push(c); }
                        None => break,
                    }
                }
                Some(c) if c == quote => {
                    self.advance();
                    break;
                }
                Some(c) => {
                    s.push(c);
                    self.advance();
                }
            }
        }
        Token {
            kind: TokenKind::StringLiteral(s),
            span: Span { start, end: self.pos },
            text: self.source[start..self.pos].to_string(),
        }
    }

    fn lex_hex_number(&mut self) -> Token {
        let start = self.pos;
        self.advance(); // 0
        self.advance(); // x
        while self.current().map(|c| c.is_ascii_hexdigit() || c == '_').unwrap_or(false) {
            self.advance();
        }
        let text = self.source[start..self.pos].to_string();
        Token {
            kind: TokenKind::HexLiteral(text.clone()),
            span: Span { start, end: self.pos },
            text,
        }
    }

    fn lex_number(&mut self) -> Token {
        let start = self.pos;
        while self.current().map(|c| c.is_ascii_digit() || c == '_' || c == '.').unwrap_or(false) {
            self.advance();
        }
        // Check for 'e' or 'E' exponent
        if self.current() == Some('e') || self.current() == Some('E') {
            self.advance();
            if self.current() == Some('-') || self.current() == Some('+') {
                self.advance();
            }
            while self.current().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                self.advance();
            }
        }
        // Check for unit suffix (ether, gwei, wei, seconds, minutes, hours, days, weeks)
        let text = self.source[start..self.pos].to_string();
        Token {
            kind: TokenKind::NumberLiteral(text.clone()),
            span: Span { start, end: self.pos },
            text,
        }
    }

    fn lex_identifier_or_keyword(&mut self) -> Token {
        let start = self.pos;
        while self.current().map(|c| c.is_alphanumeric() || c == '_' || c == '$').unwrap_or(false) {
            self.advance();
        }
        let text = &self.source[start..self.pos];

        let kind = match text {
            "pragma" => TokenKind::Pragma,
            "import" => TokenKind::Import,
            "contract" => TokenKind::Contract,
            "library" => TokenKind::Library,
            "interface" => TokenKind::Interface,
            "abstract" => TokenKind::Abstract,
            "is" => TokenKind::Is,
            "constructor" => TokenKind::Constructor,
            "function" => TokenKind::Function,
            "event" => TokenKind::Event,
            "error" => TokenKind::Error,
            "struct" => TokenKind::Struct,
            "enum" => TokenKind::Enum,
            "mapping" => TokenKind::Mapping,
            "modifier" => TokenKind::Modifier,
            "using" => TokenKind::Using,
            "type" => TokenKind::Type,
            "public" => TokenKind::Public,
            "private" => TokenKind::Private,
            "external" => TokenKind::External,
            "internal" => TokenKind::Internal,
            "pure" => TokenKind::Pure,
            "view" => TokenKind::View,
            "payable" => TokenKind::Payable,
            "immutable" => TokenKind::Immutable,
            "constant" => TokenKind::Constant,
            "virtual" => TokenKind::Virtual,
            "override" => TokenKind::Override,
            "anonymous" => TokenKind::Anonymous,
            "indexed" => TokenKind::Indexed,
            "memory" => TokenKind::Memory,
            "storage" => TokenKind::Storage,
            "calldata" => TokenKind::Calldata,
            "if" => TokenKind::If,
            "else" => TokenKind::Else,
            "while" => TokenKind::While,
            "do" => TokenKind::Do,
            "for" => TokenKind::For_,
            "break" => TokenKind::Break,
            "continue" => TokenKind::Continue,
            "return" => TokenKind::Return,
            "emit" => TokenKind::Emit,
            "revert" => TokenKind::Revert,
            "delete" => TokenKind::Delete,
            "new" => TokenKind::New,
            "address" => TokenKind::Address,
            "bool" => TokenKind::Bool,
            "string" => TokenKind::String_,
            "bytes" => TokenKind::Bytes,
            "int" => TokenKind::Int(256),
            "uint" => TokenKind::Uint(256),
            "fixed" => TokenKind::Fixed,
            "ufixed" => TokenKind::Ufixed,
            "true" => TokenKind::BoolLiteral(true),
            "false" => TokenKind::BoolLiteral(false),
            "returns" => TokenKind::Returns,
            "fallback" => TokenKind::Fallback,
            "receive" => TokenKind::Receive,
            "assembly" => TokenKind::Assembly,
            "unchecked" => TokenKind::Unchecked,
            "try" => TokenKind::Try,
            "catch" => TokenKind::Catch,
            "_" => TokenKind::Underscore,
            _ => {
                // Check for intN, uintN, bytesN
                if let Some(kind) = parse_sized_type(text) {
                    kind
                } else {
                    TokenKind::Identifier(text.to_string())
                }
            }
        };

        Token {
            kind,
            span: Span { start, end: self.pos },
            text: text.to_string(),
        }
    }
}

fn parse_sized_type(s: &str) -> Option<TokenKind> {
    if s.starts_with("uint") && s.len() > 4 {
        let n: u16 = s[4..].parse().ok()?;
        if n >= 8 && n <= 256 && n % 8 == 0 {
            return Some(TokenKind::Uint(n));
        }
    }
    if s.starts_with("int") && s.len() > 3 {
        let n: u16 = s[3..].parse().ok()?;
        if n >= 8 && n <= 256 && n % 8 == 0 {
            return Some(TokenKind::Int(n));
        }
    }
    if s.starts_with("bytes") && s.len() > 5 {
        let n: u8 = s[5..].parse().ok()?;
        if n >= 1 && n <= 32 {
            return Some(TokenKind::Bytes_(n));
        }
    }
    None
}

pub fn tokenize(source: &str) -> Vec<Token> {
    let mut lexer = Lexer::new(source);
    let mut tokens = Vec::new();
    loop {
        let tok = lexer.next_token();
        let is_eof = tok.kind == TokenKind::Eof;
        tokens.push(tok);
        if is_eof {
            break;
        }
    }
    tokens
}
