fn format_human_error(
    msg: &str,
    code: Option<&str>,
    file: &str,
    line: usize,
    col: usize,
    span_len: usize,
    line_text: &str,
    style: &str,
    use_color: bool,
    note: Option<&str>,
    extra_notes: &[crate::resolver::NoteSpan],
) -> String {
    let mut out = String::new();

    let error_prefix = if let Some(c) = code {
        format!("error[{}]", c)
    } else {
        "error".to_string()
    };

