                out.push_str(&format!("\x1b[1m{}\x1b[0m:\x1b[1m{}:{}\x1b[0m: \x1b[1m\x1b[91merror\x1b[0m\x1b[1m: {}\x1b[0m",
                    file, line, col, msg));
            } else {
                out.push_str(&format!("{}:{}:{}: {}: {}", file, line, col, error_prefix, msg));
            }
            out.push('\n');

            // Add notes
            for note_span in extra_notes {
                let (nl, nc) = offset_to_line_col(&note_span.content, note_span.span.start);
                if use_color {
                    out.push_str(&format!("\x1b[1m{}\x1b[0m:\x1b[1m{}:{}\x1b[0m: \x1b[1m\x1b[96mnote\x1b[0m\x1b[1m: {}\x1b[0m\n",
                        note_span.file, nl, nc, note_span.message));
                } else {
                    out.push_str(&format!("{}:{}:{}: note: {}\n", note_span.file, nl, nc, note_span.message));
                }
            }

            // Aborting message handled separately
        }
        "ascii" => {
            format_ascii_error(&mut out, msg, code, file, line, col, span_len, line_text, use_color, note, extra_notes);
        }
        _ => {
            // unicode (default)
            format_unicode_error(&mut out, msg, code, file, line, col, span_len, line_text, use_color, note, extra_notes);
        }
    }

    out
}

