    diagnostic_width: Option<usize>,
) {
    let (line, col) = offset_to_line_col(content, err.span.start);
    let span_len = if err.span.end > err.span.start { err.span.end - err.span.start } else { 1 };
    let line_text = get_line(content, line);

    match format {
        "json" => {
            let human_msg = format_human_error(
                &err.message, None, file, line, col, span_len, &line_text, style, use_color,
                err.note.as_deref(), &[]
            );
            let formatted_escaped = escape_json(&human_msg);
            let msg_escaped = escape_json(&err.message);
            eprintln!("{{\"sourceLocation\":{{\"file\":\"{}\",\"start\":{},\"end\":{}}},\"secondarySourceLocations\":[],\"type\":\"Exception\",\"component\":\"general\",\"severity\":\"error\",\"errorCode\":null,\"message\":\"{}\",\"formattedMessage\":\"{}\"}}",
                escape_json(file), err.span.start, err.span.end,
                msg_escaped, formatted_escaped);
        }
        "rustc-json" => {
            let human_msg = format_human_error(
                &err.message, None, file, line, col, span_len, &line_text, style, false,
                err.note.as_deref(), &[]
            );
            let formatted_escaped = escape_json(&human_msg);
            let msg_escaped = escape_json(&err.message);
            let label_escaped = escape_json(err.label.as_deref().unwrap_or(""));
            let line_text_escaped = escape_json(&line_text);
            eprintln!("{{\"$message_type\":\"diagnostic\",\"message\":\"{}\",\"code\":null,\"level\":\"error\",\"spans\":[{{\"file_name\":\"{}\",\"byte_start\":{},\"byte_end\":{},\"line_start\":{},\"line_end\":{},\"column_start\":{},\"column_end\":{},\"is_primary\":true,\"text\":[{{\"text\":\"{}\",\"highlight_start\":{},\"highlight_end\":{}}}],\"label\":\"{}\",\"suggested_replacement\":null}}],\"children\":[],\"rendered\":\"{}\"}}",
                msg_escaped,
                escape_json(file),
                err.span.start, err.span.end,
                line, line, col, col + span_len,
                line_text_escaped, col, col + span_len,
                label_escaped,
                formatted_escaped);
        }
        _ => {
            let human_msg = format_human_error(
                &err.message, None, file, line, col, span_len, &line_text, style, use_color,
                err.note.as_deref(), &[]
            );
            eprint!("{}", human_msg);
        }
    }
}

pub fn emit_analysis_error(
    err: &AnalysisError,
    format: &str,
    style: &str,
    use_color: bool,
    diagnostic_width: Option<usize>,
) {
    let (line, col) = offset_to_line_col(&err.content, err.span.start);
    let span_len = if err.span.end > err.span.start { err.span.end - err.span.start } else { 1 };
    let line_text = get_line(&err.content, line);

    // Build secondary spans
    let mut secondaries = Vec::new();
    for note in &err.notes {
        secondaries.push(note.clone());
    }

    match format {
        "json" => {
            let human_msg = format_human_error(
                &err.message, err.code.as_deref(), &err.file, line, col, span_len, &line_text, style, use_color,
                None, &err.notes
            );
            let formatted_escaped = escape_json(&human_msg);
            let msg_escaped = escape_json(&err.message);
            let src_loc = if err.file.is_empty() {
                "null".to_string()
            } else {
                format!("{{\"file\":\"{}\",\"start\":{},\"end\":{}}}", 
                    escape_json(&err.file), err.span.start, err.span.end)
            };
            eprintln!("{{\"sourceLocation\":{},\"secondarySourceLocations\":[],\"type\":\"Exception\",\"component\":\"general\",\"severity\":\"{}\",\"errorCode\":null,\"message\":\"{}\",\"formattedMessage\":\"{}\"}}",
                src_loc, err.severity, msg_escaped, formatted_escaped);
        }
        "rustc-json" => {
            let human_msg = format_human_error(
                &err.message, err.code.as_deref(), &err.file, line, col, span_len, &line_text, style, false,
                None, &err.notes
            );
            let formatted_escaped = escape_json(&human_msg);
            let msg_escaped = escape_json(&err.message);
            eprintln!("{{\"$message_type\":\"diagnostic\",\"message\":\"{}\",\"code\":null,\"level\":\"{}\",\"spans\":[],\"children\":[],\"rendered\":\"{}\"}}",
                msg_escaped, err.severity, formatted_escaped);
        }
        _ => {
            let human_msg = format_human_error(
                &err.message, err.code.as_deref(), &err.file, line, col, span_len, &line_text, style, use_color,
                None, &err.notes
            );
            eprint!("{}", human_msg);
        }
    }
}

fn format_severity(sev: &str, use_color: bool) -> String {
    if use_color {
        match sev {
            "error" => "\x1b[1m\x1b[91merror\x1b[0m".to_string(),
            "warning" => "\x1b[1m\x1b[93mwarning\x1b[0m".to_string(),
            "note" => "\x1b[1m\x1b[96mnote\x1b[0m".to_string(),
            _ => sev.to_string(),
        }
    } else {
        sev.to_string()
    }
}

fn format_error_prefix(sev: &str, code: Option<&str>, use_color: bool) -> String {
    let code_str = code.map(|c| format!("[{}]", c)).unwrap_or_default();
    if use_color {
        match sev {
            "error" => format!("\x1b[1m\x1b[91merror{}\x1b[0m", code_str),
            "warning" => format!("\x1b[1m\x1b[93mwarning{}\x1b[0m", code_str),
            "note" => format!("\x1b[1m\x1b[96mnote\x1b[0m"),
            _ => format!("{}{}", sev, code_str),
        }
    } else {
        format!("{}{}", sev, code_str)
    }
}

fn format_human_error(
    msg: &str,
    code: Option<&str>,
    file: &str,
    line: usize,
    col: usize,
    span_len: usize,
    line_text: &str,
    style: &str,
    use_color: bool,
    note: Option<&str>,
    extra_notes: &[crate::resolver::NoteSpan],
) -> String {
    let mut out = String::new();

    let error_prefix = if let Some(c) = code {
        format!("error[{}]", c)
    } else {
        "error".to_string()
    };

    match style {
        "short" => {
            if use_color {
                out.push_str(&format!("\x1b[1m{}\x1b[0m:\x1b[1m{}:{}\x1b[0m: \x1b[1m\x1b[91merror\x1b[0m\x1b[1m: {}\x1b[0m",
                    file, line, col, msg));
            } else {
                out.push_str(&format!("{}:{}:{}: {}: {}", file, line, col, error_prefix, msg));
            }
            out.push('\n');

            // Add notes
            for note_span in extra_notes {
                let (nl, nc) = offset_to_line_col(&note_span.content, note_span.span.start);
                if use_color {
                    out.push_str(&format!("\x1b[1m{}\x1b[0m:\x1b[1m{}:{}\x1b[0m: \x1b[1m\x1b[96mnote\x1b[0m\x1b[1m: {}\x1b[0m\n",
                        note_span.file, nl, nc, note_span.message));
                } else {
                    out.push_str(&format!("{}:{}:{}: note: {}\n", note_span.file, nl, nc, note_span.message));
                }
            }

            // Aborting message handled separately
        }
        "ascii" => {
            format_ascii_error(&mut out, msg, code, file, line, col, span_len, line_text, use_color, note, extra_notes);
        }
        _ => {
            // unicode (default)
            format_unicode_error(&mut out, msg, code, file, line, col, span_len, line_text, use_color, note, extra_notes);
        }
    }

    out
}

fn format_unicode_error(
    out: &mut String,
    msg: &str,
    code: Option<&str>,
    file: &str,
    line: usize,
    col: usize,
    span_len: usize,
    line_text: &str,
    use_color: bool,
    note: Option<&str>,
    extra_notes: &[crate::resolver::NoteSpan],
) {
    // "error: message"
    let error_prefix = if let Some(c) = code {
        format!("error[{}]", c)
    } else {
        "error".to_string()
    };

    if use_color {
        out.push_str(&format!("\x1b[1m\x1b[91m{}\x1b[0m\x1b[1m: {}\x1b[0m\n", error_prefix, msg));
    } else {
        out.push_str(&format!("{}: {}\n", error_prefix, msg));
    }

    // Location line: "  ╭▸ file:line:col"
    let line_num_width = line.to_string().len();

    if use_color {
        out.push_str(&format!("  \x1b[1m\x1b[94m╭▸ \x1b[0m{}:{}:{}\n", file, line, col));
        out.push_str(&format!("  \x1b[1m\x1b[94m│\x1b[0m\n"));
        out.push_str(&format!("\x1b[1m\x1b[94m{}\x1b[0m \x1b[1m\x1b[94m│\x1b[0m {}\n", line, line_text));
    } else {
        out.push_str(&format!("  ╭▸ {}:{}:{}\n", file, line, col));
        out.push_str(&format!("  │\n"));
        out.push_str(&format!("{} │ {}\n", line, line_text));
    }

    // Underline
    let underline = if span_len == 1 {
        "━".to_string()
    } else {
        "━".repeat(span_len)
    };

    let padding = " ".repeat(col - 1);

    if use_color {
        if let Some(code) = code {
            // has help note inline
            // Print special format for error[code] - has help in middle
            // (handled separately for specific error types)
        }
        out.push_str(&format!("  \x1b[1m\x1b[94m╰╴\x1b[0m{}\x1b[1m\x1b[91m{}\x1b[0m\n", padding, underline));
    } else {
        out.push_str(&format!("  ╰╴{}{}\n", padding, underline));
    }

    // Note if present
    if let Some(note_msg) = note {
        if use_color {
            out.push_str(&format!("  \x1b[1m\x1b[94m│\x1b[0m\n"));
            out.push_str(&format!("  \x1b[1m\x1b[94m╰\x1b[0m \x1b[1m\x1b[96mnote\x1b[0m: {}\n", note_msg));
        } else {
            out.push_str(&format!("  │\n"));
            out.push_str(&format!("  ╰ note: {}\n", note_msg));
        }
    }

    // Extra notes (secondary spans)
    for note_span in extra_notes {
        let (nl, nc) = offset_to_line_col(&note_span.content, note_span.span.start);
        let nspan_len = if note_span.span.end > note_span.span.start { note_span.span.end - note_span.span.start } else { 1 };
        let nline_text = get_line(&note_span.content, nl);
        let nunderline = "━".repeat(nspan_len);
        let npadding = " ".repeat(nc - 1);

        if use_color {
            out.push_str(&format!("\x1b[1m\x1b[96mnote\x1b[0m\x1b[1m: {}\x1b[0m\n", note_span.message));
            out.push_str(&format!("  \x1b[1m\x1b[94m╭▸ \x1b[0m{}:{}:{}\n", note_span.file, nl, nc));
            out.push_str(&format!("  \x1b[1m\x1b[94m│\x1b[0m\n"));
            out.push_str(&format!("\x1b[1m\x1b[94m{}\x1b[0m \x1b[1m\x1b[94m│\x1b[0m {}\n", nl, nline_text));
            out.push_str(&format!("  \x1b[1m\x1b[94m╰╴\x1b[0m{}\x1b[1m\x1b[91m{}\x1b[0m\n", npadding, nunderline));
        } else {
            out.push_str(&format!("note: {}\n", note_span.message));
            out.push_str(&format!("  ╭▸ {}:{}:{}\n", note_span.file, nl, nc));
            out.push_str(&format!("  │\n"));
            out.push_str(&format!("{} │ {}\n", nl, nline_text));
            out.push_str(&format!("  ╰╴{}{}\n", npadding, nunderline));
        }
    }

    out.push('\n');
}

fn format_ascii_error(
    out: &mut String,
    msg: &str,
    code: Option<&str>,
    file: &str,
    line: usize,
    col: usize,
    span_len: usize,
    line_text: &str,
    use_color: bool,
    note: Option<&str>,
    extra_notes: &[crate::resolver::NoteSpan],
) {
    let error_prefix = if let Some(c) = code {
        format!("error[{}]", c)
    } else {
        "error".to_string()
    };

    if use_color {
        out.push_str(&format!("\x1b[1m\x1b[91m{}\x1b[0m\x1b[1m: {}\x1b[0m\n", error_prefix, msg));
        out.push_str(&format!(" \x1b[1m\x1b[94m-->\x1b[0m {}:{}:{}\n", file, line, col));
        out.push_str(&format!("  \x1b[1m\x1b[94m|\x1b[0m\n"));
        out.push_str(&format!("\x1b[1m\x1b[94m{}\x1b[0m \x1b[1m\x1b[94m|\x1b[0m {}\n", line, line_text));
    } else {
        out.push_str(&format!("{}: {}\n", error_prefix, msg));
        out.push_str(&format!(" --> {}:{}:{}\n", file, line, col));
        out.push_str(&format!("  |\n"));
        out.push_str(&format!("{} | {}\n", line, line_text));
    }

    let underline = if span_len == 1 {
        "^".to_string()
    } else {
        "^".repeat(span_len)
    };
    let padding = " ".repeat(col - 1);
    let label = if let Some(lbl) = extra_notes.first() {
        // use label from first note for this span
        format!(" {}", lbl.message)
    } else if let Some(n) = note {
        format!(" {}", n)
    } else {
        // Might have label from parse error
        String::new()
    };

    if use_color {
        out.push_str(&format!("  \x1b[1m\x1b[94m|\x1b[0m {}{}\x1b[1m\x1b[91m{}{}\x1b[0m\n", 
            " ".repeat(line.to_string().len()), padding, underline, label));
    } else {
        out.push_str(&format!("  | {}{}{}{}\n", " ".repeat(line.to_string().len()), padding, underline, label));
    }

    // Extra notes
    for note_span in extra_notes {
        let (nl, nc) = offset_to_line_col(&note_span.content, note_span.span.start);
        let nspan_len = if note_span.span.end > note_span.span.start { note_span.span.end - note_span.span.start } else { 1 };
        let nline_text = get_line(&note_span.content, nl);
        let nunderline = "^".repeat(nspan_len);
        let npadding = " ".repeat(nc - 1);

        if use_color {
            out.push_str(&format!("\x1b[1m\x1b[96mnote\x1b[0m\x1b[1m: {}\x1b[0m\n", note_span.message));
            out.push_str(&format!(" \x1b[1m\x1b[94m-->\x1b[0m {}:{}:{}\n", note_span.file, nl, nc));
            out.push_str(&format!("  \x1b[1m\x1b[94m|\x1b[0m\n"));
            out.push_str(&format!("\x1b[1m\x1b[94m{}\x1b[0m \x1b[1m\x1b[94m|\x1b[0m {}\n", nl, nline_text));
            out.push_str(&format!("  \x1b[1m\x1b[94m|\x1b[0m {}{}{}\n", 
                " ".repeat(nl.to_string().len()), npadding, nunderline));
        } else {
            out.push_str(&format!("note: {}\n", note_span.message));
            out.push_str(&format!(" --> {}:{}:{}\n", note_span.file, nl, nc));
            out.push_str(&format!("  |\n"));
            out.push_str(&format!("{} | {}\n", nl, nline_text));
            out.push_str(&format!("  | {}{}{}\n", " ".repeat(nl.to_string().len()), npadding, nunderline));
        }
    }

    out.push('\n');
}

pub fn offset_to_line_col(content: &str, offset: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    let safe_offset = offset.min(content.len());
    for (i, c) in content.char_indices() {
        if i >= safe_offset {
            break;
        }
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

pub fn get_line(content: &str, line_num: usize) -> String {
    content.lines()
        .nth(line_num - 1)
        .unwrap_or("")
        .to_string()
}

pub fn escape_json(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 32 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}
