    }

    fn current(&self) -> &Token {
        &self.tokens[self.pos.min(self.tokens.len() - 1)]
    }

    fn peek(&self, offset: usize) -> &Token {
        &self.tokens[(self.pos + offset).min(self.tokens.len() - 1)]
    }

    fn advance(&mut self) -> &Token {
        let tok = &self.tokens[self.pos.min(self.tokens.len() - 1)];
        if self.pos < self.tokens.len() - 1 {
            self.pos += 1;
        }
        tok
    }

    fn at_eof(&self) -> bool {
        self.current().kind == TokenKind::Eof
    }

    fn expect(&mut self, expected: &TokenKind) -> Result<Token, ParseError> {
        if self.current().kind == *expected {
            Ok(self.advance().clone())
        } else {
            let cur = self.current().clone();
            Err(ParseError {
                message: format!("expected `{}`, found `{}`", token_name(expected), token_display(&cur)),
                span: cur.span,
                label: Some(format!("expected `{}`", token_name(expected))),
                note: None,
                code: None,
            })
        }
    }

    fn expect_identifier(&mut self) -> Result<(String, Span), ParseError> {
        match self.current().kind.clone() {
            TokenKind::Identifier(name) => {
                let span = self.current().span;
                self.advance();
                Ok((name, span))
            }
            // Some keywords can be used as identifiers
            _ if is_keyword_usable_as_identifier(&self.current().kind) => {
                let name = self.current().text.clone();
                let span = self.current().span;
                self.advance();
                Ok((name, span))
            }
            _ => {
                let cur = self.current().clone();
                Err(ParseError {
                    message: format!("expected identifier, found `{}`", token_display(&cur)),
                    span: cur.span,
                    label: None,
                    note: None,
                    code: None,
                })
            }
        }
    }

    fn eat(&mut self, kind: &TokenKind) -> bool {
        if self.current().kind == *kind {
            self.advance();
            true
        } else {
            false
        }
    }

    pub fn parse_source_unit(&mut self) -> SourceUnit {
        let mut items = Vec::new();

        while !self.at_eof() {
            match self.parse_source_unit_item() {
                Ok(item) => items.push(item),
                Err(e) => {
                    self.errors.push(e);
                    // Error recovery: skip to next top-level item
                    self.recover_to_next_toplevel();
                    if self.errors.len() >= 10 {
                        break; // stop after many errors
                    }
                }
            }
        }

        SourceUnit { items }
    }

    fn recover_to_next_toplevel(&mut self) {
        // Skip tokens until we find a top-level keyword
        loop {
            if self.at_eof() {
                break;
            }
            match self.current().kind {
                TokenKind::Contract | TokenKind::Library | TokenKind::Interface |
                TokenKind::Abstract | TokenKind::Pragma | TokenKind::Import |
                TokenKind::Function | TokenKind::Event | TokenKind::Error |
                TokenKind::Struct | TokenKind::Enum | TokenKind::Type => {
                    break;
                }
                _ => { self.advance(); }
            }
        }
    }

    fn parse_source_unit_item(&mut self) -> Result<SourceUnitItem, ParseError> {
        match self.current().kind.clone() {
            TokenKind::Pragma => {
                let prag = self.parse_pragma()?;
                Ok(SourceUnitItem::PragmaDirective(prag))
            }
            TokenKind::Import => {
                let imp = self.parse_import()?;
                Ok(SourceUnitItem::ImportDirective(imp))
            }
            TokenKind::Contract => {
                let c = self.parse_contract(ContractKind::Contract)?;
                Ok(SourceUnitItem::ContractDefinition(c))
            }
            TokenKind::Library => {
                let c = self.parse_contract(ContractKind::Library)?;
                Ok(SourceUnitItem::ContractDefinition(c))
            }
            TokenKind::Interface => {
                let c = self.parse_contract(ContractKind::Interface)?;
                Ok(SourceUnitItem::ContractDefinition(c))
            }
            TokenKind::Abstract => {
                self.advance(); // abstract
                // expect 'contract'
                match self.current().kind {
                    TokenKind::Contract => {
                        let c = self.parse_contract(ContractKind::Abstract)?;
                        Ok(SourceUnitItem::ContractDefinition(c))
                    }
                    _ => {
                        let cur = self.current().clone();
                        Err(ParseError {
                            message: format!("expected `contract`, found `{}`", token_display(&cur)),
                            span: cur.span,
                            label: None, note: None, code: None,
                        })
                    }
                }
            }
            TokenKind::Function => {
                let f = self.parse_function()?;
                Ok(SourceUnitItem::FunctionDefinition(f))
            }
            TokenKind::Error => {
                let e = self.parse_error_def()?;
                Ok(SourceUnitItem::ErrorDefinition(e))
            }
            TokenKind::Event => {
                let e = self.parse_event_def()?;
                Ok(SourceUnitItem::EventDefinition(e))
            }
            TokenKind::Struct => {
                let s = self.parse_struct_def()?;
                Ok(SourceUnitItem::StructDefinition(s))
            }
            TokenKind::Enum => {
                let e = self.parse_enum_def()?;
                Ok(SourceUnitItem::EnumDefinition(e))
            }
            TokenKind::Type => {
                let t = self.parse_user_defined_value_type()?;
                Ok(SourceUnitItem::UserDefinedValueType(t))
            }
            TokenKind::Using => {
                let u = self.parse_using_directive()?;
                Ok(SourceUnitItem::UsingDirective(u))
            }
            // Free-standing state variable or constant
            _ if self.is_type_start() => {
                // Could be a free variable declaration
                let sv = self.parse_state_variable_declaration()?;
                Ok(SourceUnitItem::StateVariableDeclaration(sv))
            }
            _ => {
                let cur = self.current().clone();
                let possible = "pragma, import directive, contract, interface, library, struct, enum, constant, function, modifier, or error definition";
                Err(ParseError {
                    message: format!("expected global item ({}), found `{}`", possible, token_display(&cur)),
                    span: cur.span,
                    label: None,
                    note: Some("for a full list of valid global items, see <https://docs.soliditylang.org/en/latest/grammar.html#a4.SolidityParser.sourceUnit>".to_string()),
                    code: None,
                })
            }
        }
    }

    fn parse_pragma(&mut self) -> Result<PragmaDirective, ParseError> {
        self.advance(); // 'pragma'
        let mut content = String::new();
        while !self.at_eof() && self.current().kind != TokenKind::Semicolon {
            content.push_str(&self.current().text);
            content.push(' ');
            self.advance();
        }
        self.eat(&TokenKind::Semicolon);
        Ok(PragmaDirective { content: content.trim().to_string() })
    }

    fn parse_import(&mut self) -> Result<ImportDirective, ParseError> {
        self.advance(); // 'import'

        match self.current().kind.clone() {
            TokenKind::StringLiteral(path) => {
                let path = path.clone();
                self.advance();

                let alias = if self.eat(&TokenKind::Identifier("as".to_string())) || 
                              (matches!(self.current().kind, TokenKind::Identifier(_)) && self.current().text == "as") {
                    if self.current().text == "as" { self.advance(); }
                    let (name, _) = self.expect_identifier()?;
                    Some(name)
                } else {
                    None
                };

                self.eat(&TokenKind::Semicolon);
                Ok(ImportDirective { path, alias, symbols: Vec::new() })
            }
            TokenKind::Star => {
                self.advance(); // *
                // 'as' alias
                let alias = if self.current().text == "as" {
                    self.advance();
                    let (name, _) = self.expect_identifier()?;
                    Some(name)
                } else { None };

                if self.current().text == "from" {
                    self.advance(); // from
                }
                let path = if let TokenKind::StringLiteral(p) = self.current().kind.clone() {
                    self.advance();
                    p
                } else { String::new() };

                self.eat(&TokenKind::Semicolon);
                Ok(ImportDirective { path, alias, symbols: Vec::new() })
            }
            TokenKind::LBrace => {
                self.advance(); // {
                let mut symbols = Vec::new();

                while !self.at_eof() && self.current().kind != TokenKind::RBrace {
                    let (name, _) = self.expect_identifier()?;
                    let alias = if self.current().text == "as" {
                        self.advance();
                        let (a, _) = self.expect_identifier()?;
                        Some(a)
                    } else { None };
                    symbols.push((name, alias));
                    if !self.eat(&TokenKind::Comma) {
                        break;
                    }
                }
                self.eat(&TokenKind::RBrace);

                if self.current().text == "from" {
                    self.advance();
                }
                let path = if let TokenKind::StringLiteral(p) = self.current().kind.clone() {
                    self.advance();
                    p
                } else { String::new() };

                self.eat(&TokenKind::Semicolon);
                Ok(ImportDirective { path, alias: None, symbols })
            }
            _ => {
                let cur = self.current().clone();
                Err(ParseError {
                    message: format!("expected string literal for import path, found `{}`", token_display(&cur)),
                    span: cur.span,
                    label: None, note: None, code: None,
                })
            }
        }
    }

    fn parse_contract(&mut self, kind: ContractKind) -> Result<ContractDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // contract/library/interface keyword

        let (name, _) = self.expect_identifier()?;

        let mut base_contracts = Vec::new();
        if self.eat(&TokenKind::Is) {
            loop {
                let (base_name, _) = self.expect_identifier()?;
                let mut full_name = base_name;
                while self.eat(&TokenKind::Dot) {
                    let (part, _) = self.expect_identifier()?;
                    full_name = format!("{}.{}", full_name, part);
                }
                // Optional constructor args
                if self.current().kind == TokenKind::LParen {
                    self.skip_parens();
                }
                base_contracts.push(InheritanceSpecifier {
                    name: full_name,
                    args: Vec::new(),
                });
                if !self.eat(&TokenKind::Comma) {
                    break;
                }
            }
        }

        let contract_span = Span { start, end: self.current().span.end };
        self.expect(&TokenKind::LBrace)?;

        let mut items = Vec::new();

        while !self.at_eof() && self.current().kind != TokenKind::RBrace {
            match self.parse_contract_item() {
                Ok(item) => items.push(item),
                Err(e) => {
                    self.errors.push(e);
                    // recover
                    self.recover_in_contract();
                    if self.errors.len() >= 10 { break; }
                }
            }
        }

        self.eat(&TokenKind::RBrace);

        Ok(ContractDefinition {
            kind,
            name,
            base_contracts,
            items,
            span: contract_span,
        })
    }

    fn recover_in_contract(&mut self) {
        let mut depth = 0i32;
        loop {
            if self.at_eof() { break; }
            match self.current().kind {
                TokenKind::LBrace => {
                    depth += 1;
                    self.advance();
                }
                TokenKind::RBrace => {
                    if depth == 0 { break; }
                    depth -= 1;
                    self.advance();
                }
                TokenKind::Function | TokenKind::Event | TokenKind::Error |
                TokenKind::Struct | TokenKind::Enum | TokenKind::Modifier |
                TokenKind::Constructor | TokenKind::Fallback | TokenKind::Receive => {
                    if depth == 0 { break; }
                    self.advance();
                }
                _ => { self.advance(); }
            }
        }
    }

    fn parse_contract_item(&mut self) -> Result<ContractItem, ParseError> {
        match self.current().kind.clone() {
            TokenKind::Function => {
                let f = self.parse_function()?;
                Ok(ContractItem::FunctionDefinition(f))
            }
            TokenKind::Constructor => {
                let f = self.parse_constructor()?;
                Ok(ContractItem::ConstructorDefinition(f))
            }
            TokenKind::Fallback => {
                let f = self.parse_fallback()?;
                Ok(ContractItem::FallbackDefinition(f))
            }
            TokenKind::Receive => {
                let f = self.parse_receive()?;
                Ok(ContractItem::ReceiveDefinition(f))
            }
            TokenKind::Event => {
                let e = self.parse_event_def()?;
                Ok(ContractItem::EventDefinition(e))
            }
            TokenKind::Error => {
                let e = self.parse_error_def()?;
                Ok(ContractItem::ErrorDefinition(e))
            }
            TokenKind::Struct => {
                let s = self.parse_struct_def()?;
                Ok(ContractItem::StructDefinition(s))
            }
            TokenKind::Enum => {
                let e = self.parse_enum_def()?;
                Ok(ContractItem::EnumDefinition(e))
            }
            TokenKind::Modifier => {
                let m = self.parse_modifier_def()?;
                Ok(ContractItem::ModifierDefinition(m))
            }
            TokenKind::Using => {
                let u = self.parse_using_directive()?;
                Ok(ContractItem::UsingDirective(u))
            }
            TokenKind::Type => {
                let t = self.parse_user_defined_value_type()?;
                Ok(ContractItem::UserDefinedValueType(t))
            }
            _ if self.is_type_start() => {
                let sv = self.parse_state_variable_declaration()?;
                Ok(ContractItem::StateVariableDeclaration(sv))
            }
            _ => {
                let cur = self.current().clone();
                Err(ParseError {
                    message: format!("expected contract item, found `{}`", token_display(&cur)),
                    span: cur.span,
                    label: None, note: None, code: None,
                })
            }
        }
    }

    fn parse_function(&mut self) -> Result<FunctionDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'function'

        let name = if self.current().kind == TokenKind::LParen {
            // anonymous function (old style fallback)
            None
        } else {
            match self.current().kind.clone() {
                TokenKind::Identifier(n) => {
                    self.advance();
                    Some(n)
                }
                _ if is_keyword_usable_as_identifier(&self.current().kind) => {
                    let n = self.current().text.clone();
                    self.advance();
                    Some(n)
                }
                _ => {
                    let cur = self.current().clone();
                    return Err(ParseError {
                        message: format!("expected function name, found `{}`", token_display(&cur)),
                        span: cur.span,
                        label: None, note: None, code: None,
                    });
                }
            }
        };

        let params = self.parse_parameter_list()?;
        let (visibility, mutability, is_virtual, is_override, modifiers) = self.parse_function_attributes()?;

        let return_params = if self.eat(&TokenKind::Returns) {
            self.parse_parameter_list()?
        } else {
            Vec::new()
        };

        let span = Span { start, end: self.current().span.end };

        let body = if self.current().kind == TokenKind::Semicolon {
            self.advance();
            None
        } else if self.current().kind == TokenKind::LBrace {
            self.skip_block();
            Some(())
        } else {
            None
        };

        Ok(FunctionDefinition {
            kind: FunctionKind::Function,
            name,
            params,
            return_params,
            visibility,
            mutability,
            modifiers,
            is_virtual,
            is_override,
            body,
            span,
        })
    }

    fn parse_constructor(&mut self) -> Result<FunctionDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'constructor'

        let params = self.parse_parameter_list()?;
        let (_, mutability, _, _, modifiers) = self.parse_function_attributes()?;

        let span = Span { start, end: self.current().span.end };

        let body = if self.current().kind == TokenKind::Semicolon {
            self.advance();
            None
        } else if self.current().kind == TokenKind::LBrace {
            self.skip_block();
            Some(())
        } else {
            None
        };

        Ok(FunctionDefinition {
            kind: FunctionKind::Constructor,
            name: None,
            params,
            return_params: Vec::new(),
            visibility: Visibility::Public,
            mutability,
            modifiers,
            is_virtual: false,
            is_override: false,
            body,
            span,
        })
    }

    fn parse_fallback(&mut self) -> Result<FunctionDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'fallback'

        let params = if self.current().kind == TokenKind::LParen {
            self.parse_parameter_list()?
        } else {
            Vec::new()
        };

        let (visibility, mutability, is_virtual, is_override, modifiers) = self.parse_function_attributes()?;

        let return_params = if self.eat(&TokenKind::Returns) {
            self.parse_parameter_list()?
        } else {
            Vec::new()
        };

        let span = Span { start, end: self.current().span.end };

        let body = if self.current().kind == TokenKind::Semicolon {
            self.advance();
            None
        } else if self.current().kind == TokenKind::LBrace {
            self.skip_block();
            Some(())
        } else {
            None
        };

        Ok(FunctionDefinition {
            kind: FunctionKind::Fallback,
            name: None,
            params,
            return_params,
            visibility,
            mutability,
            modifiers,
            is_virtual,
            is_override,
            body,
            span,
        })
    }

    fn parse_receive(&mut self) -> Result<FunctionDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'receive'

        let params = if self.current().kind == TokenKind::LParen {
            self.parse_parameter_list()?
        } else {
            Vec::new()
        };

        let (visibility, mutability, is_virtual, is_override, modifiers) = self.parse_function_attributes()?;

        let span = Span { start, end: self.current().span.end };

        let body = if self.current().kind == TokenKind::Semicolon {
            self.advance();
            None
        } else if self.current().kind == TokenKind::LBrace {
            self.skip_block();
            Some(())
        } else {
            None
        };

        Ok(FunctionDefinition {
            kind: FunctionKind::Receive,
            name: None,
            params,
            return_params: Vec::new(),
            visibility,
            mutability,
            modifiers,
            is_virtual,
            is_override,
            body,
            span,
        })
    }

    fn parse_function_attributes(&mut self) -> Result<(Visibility, Mutability, bool, bool, Vec<String>), ParseError> {
        let mut visibility = Visibility::Internal;
        let mut mutability = Mutability::NonPayable;
        let mut is_virtual = false;
        let mut is_override = false;
        let mut modifiers = Vec::new();
        let mut has_visibility = false;

        loop {
            match self.current().kind.clone() {
                TokenKind::Public => { visibility = Visibility::Public; has_visibility = true; self.advance(); }
                TokenKind::Private => { visibility = Visibility::Private; has_visibility = true; self.advance(); }
                TokenKind::External => { visibility = Visibility::External; has_visibility = true; self.advance(); }
                TokenKind::Internal => { visibility = Visibility::Internal; has_visibility = true; self.advance(); }
                TokenKind::Pure => { mutability = Mutability::Pure; self.advance(); }
                TokenKind::View => { mutability = Mutability::View; self.advance(); }
                TokenKind::Payable => { mutability = Mutability::Payable; self.advance(); }
                TokenKind::Virtual => { is_virtual = true; self.advance(); }
                TokenKind::Override => {
                    is_override = true;
                    self.advance();
                    // Optional override(Foo, Bar)
                    if self.current().kind == TokenKind::LParen {
                        self.skip_parens();
                    }
                }
                // Modifier invocations
                TokenKind::Identifier(name) => {
                    let name = name.clone();
                    modifiers.push(name);
                    self.advance();
                    // Optional modifier args
                    if self.current().kind == TokenKind::LParen {
                        self.skip_parens();
                    }
                }
                _ => break,
            }
        }

        Ok((visibility, mutability, is_virtual, is_override, modifiers))
    }

    fn parse_parameter_list(&mut self) -> Result<Vec<Parameter>, ParseError> {
        self.expect(&TokenKind::LParen)?;
        let mut params = Vec::new();

        while !self.at_eof() && self.current().kind != TokenKind::RParen {
            let param = self.parse_parameter()?;
            params.push(param);
            if !self.eat(&TokenKind::Comma) {
                break;
            }
        }

        self.expect(&TokenKind::RParen)?;
        Ok(params)
    }

    fn parse_parameter(&mut self) -> Result<Parameter, ParseError> {
        let type_ = self.parse_type()?;

        let data_location = match self.current().kind {
            TokenKind::Memory => { self.advance(); Some(DataLocation::Memory) }
            TokenKind::Storage => { self.advance(); Some(DataLocation::Storage) }
            TokenKind::Calldata => { self.advance(); Some(DataLocation::Calldata) }
            _ => None,
        };

        let name = match self.current().kind.clone() {
            TokenKind::Identifier(name) => {
                self.advance();
                Some(name)
            }
            _ if is_keyword_usable_as_identifier(&self.current().kind) => {
                let n = self.current().text.clone();
                self.advance();
                Some(n)
            }
            _ => None,
        };

        Ok(Parameter { type_, name, data_location })
    }

    fn parse_type(&mut self) -> Result<TypeName, ParseError> {
        let ty = self.parse_base_type()?;

        // Handle arrays
        let mut result = ty;
        loop {
            if self.current().kind == TokenKind::LBracket {
                self.advance(); // [
                if self.current().kind == TokenKind::RBracket {
                    self.advance(); // ]
                    result = TypeName::Array(Box::new(result), None);
                } else {
                    // fixed size - skip expression
                    let expr = self.parse_expression_in_brackets()?;
                    self.expect(&TokenKind::RBracket)?;
                    result = TypeName::Array(Box::new(result), Some(Box::new(expr)));
                }
            } else {
                break;
            }
        }

        Ok(result)
    }

    fn parse_base_type(&mut self) -> Result<TypeName, ParseError> {
        match self.current().kind.clone() {
            TokenKind::Address => {
                self.advance();
                let payable = self.eat(&TokenKind::Payable);
                Ok(TypeName::Elementary(ElementaryType::Address(payable)))
            }
            TokenKind::Bool => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::Bool))
            }
            TokenKind::String_ => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::String))
            }
            TokenKind::Bytes => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::Bytes))
            }
            TokenKind::Bytes_(n) => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::FixedBytes(n)))
            }
            TokenKind::Int(bits) => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::Int((bits / 8) as u8)))
            }
            TokenKind::Uint(bits) => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::Uint((bits / 8) as u8)))
            }
            TokenKind::Fixed => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::Fixed(16, 18)))
            }
            TokenKind::Ufixed => {
                self.advance();
                Ok(TypeName::Elementary(ElementaryType::Ufixed(16, 18)))
            }
            TokenKind::Mapping => {
                self.advance();
                self.expect(&TokenKind::LParen)?;
                let key = self.parse_type()?;
                // Optional name for key
                if let TokenKind::Identifier(_) = self.current().kind.clone() {
                    self.advance();
                }
                self.expect(&TokenKind::FatArrow)?;
                let value = self.parse_type()?;
                // Optional name for value
                if let TokenKind::Identifier(_) = self.current().kind.clone() {
                    self.advance();
                }
                self.expect(&TokenKind::RParen)?;
                Ok(TypeName::Mapping(Box::new(key), Box::new(value)))
            }
            TokenKind::Function => {
                self.advance();
                // function type
                let params_types = if self.current().kind == TokenKind::LParen {
                    let params = self.parse_parameter_list()?;
                    params.into_iter().map(|p| p.type_).collect()
                } else { Vec::new() };

                // attributes
                loop {
                    match self.current().kind {
                        TokenKind::Pure | TokenKind::View | TokenKind::Payable | 
                        TokenKind::External | TokenKind::Internal => { self.advance(); }
                        _ => break,
                    }
                }

                let return_types = if self.eat(&TokenKind::Returns) {
                    self.expect(&TokenKind::LParen)?;
                    let mut types = Vec::new();
                    while !self.at_eof() && self.current().kind != TokenKind::RParen {
                        let param = self.parse_parameter()?;
                        types.push(param.type_);
                        if !self.eat(&TokenKind::Comma) { break; }
                    }
                    self.expect(&TokenKind::RParen)?;
                    types
                } else { Vec::new() };

                Ok(TypeName::Function(params_types, return_types))
            }
            // User-defined types (paths like Foo, Foo.Bar, etc.)
            TokenKind::Identifier(_) => {
                let mut path = Vec::new();
                let (name, _) = self.expect_identifier()?;
                path.push(name);

                while self.eat(&TokenKind::Dot) {
                    let (part, _) = self.expect_identifier()?;
                    path.push(part);
                }

                Ok(TypeName::UserDefined(path))
            }
            _ if is_keyword_usable_as_identifier(&self.current().kind) => {
                let name = self.current().text.clone();
                self.advance();
                Ok(TypeName::UserDefined(vec![name]))
            }
            _ => {
                let cur = self.current().clone();
                Err(ParseError {
                    message: format!("expected type, found `{}`", token_display(&cur)),
                    span: cur.span,
                    label: None, note: None, code: None,
                })
            }
        }
    }

    fn parse_expression_in_brackets(&mut self) -> Result<Expression, ParseError> {
        // Simplified - just parse until we hit ]
        let mut depth = 0i32;
        let start = self.current().span.start;
        let mut text = String::new();
        loop {
            match self.current().kind {
                TokenKind::RBracket if depth == 0 => break,
                TokenKind::LBracket => { depth += 1; text.push_str(&self.current().text); self.advance(); }
                TokenKind::RBracket => { depth -= 1; text.push_str(&self.current().text); self.advance(); }
                TokenKind::Eof => break,
                _ => { text.push_str(&self.current().text); self.advance(); }
            }
        }
        Ok(Expression::Literal(text))
    }

    fn parse_event_def(&mut self) -> Result<EventDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'event'

        let (name, _) = self.expect_identifier()?;

        self.expect(&TokenKind::LParen)?;
        let mut params = Vec::new();

        while !self.at_eof() && self.current().kind != TokenKind::RParen {
            let type_ = self.parse_type()?;
            let indexed = self.eat(&TokenKind::Indexed);
            let data_location = match self.current().kind {
                TokenKind::Memory => { self.advance(); Some(DataLocation::Memory) }
                TokenKind::Storage => { self.advance(); Some(DataLocation::Storage) }
                TokenKind::Calldata => { self.advance(); Some(DataLocation::Calldata) }
                _ => None,
            };
            let name_opt = match self.current().kind.clone() {
                TokenKind::Identifier(n) => { self.advance(); Some(n) }
                _ if is_keyword_usable_as_identifier(&self.current().kind) => {
                    let n = self.current().text.clone();
                    self.advance();
                    Some(n)
                }
                _ => None,
            };
            params.push(EventParameter { type_, name: name_opt, indexed });
            if !self.eat(&TokenKind::Comma) { break; }
        }

        self.expect(&TokenKind::RParen)?;
        let anonymous = self.eat(&TokenKind::Anonymous);
        self.eat(&TokenKind::Semicolon);

        Ok(EventDefinition {
            name,
            params,
            anonymous,
            span: Span { start, end: self.current().span.start },
        })
    }

    fn parse_error_def(&mut self) -> Result<ErrorDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'error'

        let (name, _) = self.expect_identifier()?;

        let params = self.parse_parameter_list()?;
        self.eat(&TokenKind::Semicolon);

        Ok(ErrorDefinition {
            name,
            params,
            span: Span { start, end: self.current().span.start },
        })
    }

    fn parse_struct_def(&mut self) -> Result<StructDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'struct'

        let (name, _) = self.expect_identifier()?;
        self.expect(&TokenKind::LBrace)?;

        let mut fields = Vec::new();
        while !self.at_eof() && self.current().kind != TokenKind::RBrace {
            let type_ = self.parse_type()?;
            // data location (for struct members - optional, ignored for ABI)
            match self.current().kind {
                TokenKind::Memory | TokenKind::Storage | TokenKind::Calldata => { self.advance(); }
                _ => {}
            }
            let (fname, _) = self.expect_identifier()?;
            self.eat(&TokenKind::Semicolon);
            fields.push(StructField { type_, name: fname });
        }

        self.expect(&TokenKind::RBrace)?;

        Ok(StructDefinition {
            name,
            fields,
            span: Span { start, end: self.current().span.start },
        })
    }

    fn parse_enum_def(&mut self) -> Result<EnumDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'enum'

        let (name, _) = self.expect_identifier()?;
        self.expect(&TokenKind::LBrace)?;

        let mut values = Vec::new();
        while !self.at_eof() && self.current().kind != TokenKind::RBrace {
            let (v, _) = self.expect_identifier()?;
            values.push(v);
            if !self.eat(&TokenKind::Comma) { break; }
        }

        self.expect(&TokenKind::RBrace)?;

        Ok(EnumDefinition {
            name,
            values,
            span: Span { start, end: self.current().span.start },
        })
    }

    fn parse_modifier_def(&mut self) -> Result<ModifierDefinition, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'modifier'

        let (name, _) = self.expect_identifier()?;

        let params = if self.current().kind == TokenKind::LParen {
            self.parse_parameter_list()?
        } else {
            Vec::new()
        };

        // attributes
        loop {
            match self.current().kind {
                TokenKind::Virtual | TokenKind::Override => { self.advance(); }
                _ => break,
            }
        }

        if self.current().kind == TokenKind::Semicolon {
            self.advance();
        } else if self.current().kind == TokenKind::LBrace {
            self.skip_block();
        }

        Ok(ModifierDefinition {
            name,
            params,
            span: Span { start, end: self.current().span.start },
        })
    }

    fn parse_user_defined_value_type(&mut self) -> Result<UserDefinedValueType, ParseError> {
        let start = self.current().span.start;
        self.advance(); // 'type'

        let (name, _) = self.expect_identifier()?;

        // 'is' elementary_type
        if self.current().text == "is" {
            self.advance();
        }

        let underlying = match self.current().kind.clone() {
            TokenKind::Address => { self.advance(); ElementaryType::Address(false) }
            TokenKind::Bool => { self.advance(); ElementaryType::Bool }
            TokenKind::String_ => { self.advance(); ElementaryType::String }
            TokenKind::Bytes => { self.advance(); ElementaryType::Bytes }
            TokenKind::Bytes_(n) => { self.advance(); ElementaryType::FixedBytes(n) }
            TokenKind::Int(bits) => { self.advance(); ElementaryType::Int((bits/8) as u8) }
            TokenKind::Uint(bits) => { self.advance(); ElementaryType::Uint((bits/8) as u8) }
            _ => {
                let cur = self.current().clone();
                return Err(ParseError {
                    message: format!("expected elementary type for user-defined value type, found `{}`", token_display(&cur)),
                    span: cur.span,
                    label: None, note: None, code: None,
                });
            }
        };

        self.eat(&TokenKind::Semicolon);

        Ok(UserDefinedValueType {
            name,
            underlying,
            span: Span { start, end: self.current().span.start },
        })
    }

    fn parse_using_directive(&mut self) -> Result<UsingDirective, ParseError> {
        self.advance(); // 'using'

        // 'using Foo for Type' or 'using { Foo.add, Foo.sub } for Type'
        let library = if self.current().kind == TokenKind::LBrace {
            self.advance();
            let mut libs = Vec::new();
            loop {
                let mut name_parts = Vec::new();
                let (n, _) = self.expect_identifier()?;
                name_parts.push(n);
                while self.eat(&TokenKind::Dot) {
                    let (p, _) = self.expect_identifier()?;
                    name_parts.push(p);
                }
                libs.push(name_parts.join("."));
                // Optional 'as operator' syntax
                if self.current().text == "as" {
                    self.advance();
                    self.advance(); // operator symbol
                }
                if !self.eat(&TokenKind::Comma) { break; }
            }
            self.eat(&TokenKind::RBrace);
            libs
        } else {
            let mut name_parts = Vec::new();
            let (n, _) = self.expect_identifier()?;
            name_parts.push(n);
            while self.eat(&TokenKind::Dot) {
                let (p, _) = self.expect_identifier()?;
                name_parts.push(p);
            }
            vec![name_parts.join(".")]
        };

        // 'for' TypeName | '*'
        let type_ = if self.current().text == "for" {
            self.advance();
            if self.current().kind == TokenKind::Star {
                self.advance();
                None
            } else {
                Some(self.parse_type()?)
            }
        } else {
            None
        };

        // Optional global
        if let TokenKind::Identifier(ref s) = self.current().kind.clone() {
            if s == "global" { self.advance(); }
        }

        self.eat(&TokenKind::Semicolon);

        Ok(UsingDirective { library, type_ })
    }

    fn parse_state_variable_declaration(&mut self) -> Result<StateVariableDeclaration, ParseError> {
        let start = self.current().span.start;
        let type_ = self.parse_type()?;

        let mut visibility = Visibility::Internal;
        let mut is_constant = false;
        let mut is_immutable = false;

        loop {
            match self.current().kind {
                TokenKind::Public => { visibility = Visibility::Public; self.advance(); }
                TokenKind::Private => { visibility = Visibility::Private; self.advance(); }
                TokenKind::Internal => { visibility = Visibility::Internal; self.advance(); }
                TokenKind::Constant => { is_constant = true; self.advance(); }
                TokenKind::Immutable => { is_immutable = true; self.advance(); }
                TokenKind::Override => { self.advance(); if self.current().kind == TokenKind::LParen { self.skip_parens(); } }
                _ => break,
            }
        }

        let (name, _) = self.expect_identifier()?;

        let value = if self.eat(&TokenKind::Eq) {
            // Skip the initialization expression
            self.skip_expression();
            Some(())
        } else {
            None
        };

        self.eat(&TokenKind::Semicolon);

        Ok(StateVariableDeclaration {
            type_,
            visibility,
            name,
            value,
            is_constant,
            is_immutable,
            span: Span { start, end: self.current().span.start },
        })
    }

    fn is_type_start(&self) -> bool {
        matches!(self.current().kind,
            TokenKind::Address | TokenKind::Bool | TokenKind::String_ | 
            TokenKind::Bytes | TokenKind::Bytes_(_) | TokenKind::Int(_) | 
            TokenKind::Uint(_) | TokenKind::Mapping | TokenKind::Function |
            TokenKind::Fixed | TokenKind::Ufixed
        ) || matches!(self.current().kind, TokenKind::Identifier(_))
    }

    fn skip_block(&mut self) {
        if self.current().kind != TokenKind::LBrace {
            return;
        }
        let mut depth = 0i32;
        loop {
            match self.current().kind {
                TokenKind::LBrace => { depth += 1; self.advance(); }
                TokenKind::RBrace => {
                    depth -= 1;
                    self.advance();
                    if depth == 0 { break; }
                }
                TokenKind::Eof => break,
                _ => { self.advance(); }
            }
        }
    }

    fn skip_parens(&mut self) {
        if self.current().kind != TokenKind::LParen {
            return;
        }
        let mut depth = 0i32;
        loop {
            match self.current().kind {
                TokenKind::LParen => { depth += 1; self.advance(); }
                TokenKind::RParen => {
                    depth -= 1;
                    self.advance();
                    if depth == 0 { break; }
                }
                TokenKind::Eof => break,
                _ => { self.advance(); }
            }
        }
    }

    fn skip_expression(&mut self) {
        let mut depth = 0i32;
        loop {
            match self.current().kind {
                TokenKind::Semicolon if depth == 0 => break,
                TokenKind::Comma if depth == 0 => break,
                TokenKind::RParen if depth == 0 => break,
                TokenKind::RBracket if depth == 0 => break,
                TokenKind::LParen | TokenKind::LBracket | TokenKind::LBrace => { depth += 1; self.advance(); }
                TokenKind::RParen | TokenKind::RBracket | TokenKind::RBrace => { 
                    depth -= 1; 
                    if depth < 0 { break; }
                    self.advance();
                }
                TokenKind::Eof => break,
                _ => { self.advance(); }
            }
        }
    }
}

fn is_keyword_usable_as_identifier(kind: &TokenKind) -> bool {
    matches!(kind,
        TokenKind::From | // from in import
        TokenKind::Error | // can be used as identifier in some contexts
        TokenKind::Receive |
        TokenKind::Fallback |
        TokenKind::Constructor
    ) || false
}

// Allow 'from' and others as identifiers
impl TokenKind {
    pub fn is_from(&self) -> bool {
        matches!(self, TokenKind::Identifier(s) if s == "from")
    }
}

fn token_name(kind: &TokenKind) -> String {
    match kind {
        TokenKind::Semicolon => ";".to_string(),
        TokenKind::LParen => "(".to_string(),
        TokenKind::RParen => ")".to_string(),
        TokenKind::LBrace => "{".to_string(),
        TokenKind::RBrace => "}".to_string(),
        TokenKind::LBracket => "[".to_string(),
        TokenKind::RBracket => "]".to_string(),
        TokenKind::Comma => ",".to_string(),
        TokenKind::Dot => ".".to_string(),
        TokenKind::Eq => "=".to_string(),
        TokenKind::FatArrow => "=>".to_string(),
        TokenKind::Is => "is".to_string(),
        TokenKind::Returns => "returns".to_string(),
        TokenKind::Contract => "contract".to_string(),
        _ => format!("{:?}", kind),
    }
}

fn token_display(tok: &Token) -> String {
    match &tok.kind {
        TokenKind::Eof => "<eof>".to_string(),
        TokenKind::Identifier(s) => s.clone(),
        _ => tok.text.clone(),
    }
}

// The From token for imports
impl TokenKind {
    pub fn from_keyword() -> TokenKind {
        TokenKind::Identifier("from".to_string())
    }
}

pub fn parse(file: &str, source: &str) -> Result<SourceUnit, Vec<ParseError>> {
    let mut parser = Parser::new(file, source);
    let su = parser.parse_source_unit();

    if parser.errors.is_empty() {
        Ok(su)
    } else {
        Err(parser.errors)
    }
}
