fn check_duplicate_functions(contract: &ContractInfo, errors: &mut Vec<AnalysisError>) {
    let mut seen: std::collections::HashMap<String, Span> = std::collections::HashMap::new();

    for func in &contract.functions {
        if func.kind != FunctionKind::Function {
            continue;
        }

        let name = match &func.name {
            Some(n) => n.clone(),
            None => continue,
        };

        let sig = format!("{}({})", name, 
            func.params.iter().map(|p| type_to_abi_str(&p.type_)).collect::<Vec<_>>().join(","));

        if let Some(&prev_span) = seen.get(&sig) {
            let (line, col) = offset_to_line_col(&contract.content, prev_span.start);
            let span_end = prev_span.end;
            let span_len = span_end - prev_span.start;

            errors.push(AnalysisError {
                message: "function with same name and parameter types declared twice".to_string(),
                severity: "error".to_string(),
                code: None,
                file: contract.file.clone(),
                content: contract.content.clone(),
                span: prev_span,
                notes: vec![NoteSpan {
                    message: "other declaration".to_string(),
                    file: contract.file.clone(),
                    content: contract.content.clone(),
                    span: func.span,
                }],
                help: None,
            });
        } else {
            seen.insert(sig, func.span);
        }
    }
}

fn check_unimplemented_functions(
    contract: &ContractInfo, 
    all_contracts: &[ContractInfo],
    errors: &mut Vec<AnalysisError>
) {
    // Find functions that are virtual but have no body in this contract
    // and are not overridden
    let mut unimplemented = Vec::new();

    for func in &contract.functions {
        if func.kind != FunctionKind::Function {
            continue;
        }
        if !func.has_body || func.is_virtual {
            if !func.has_body {
                unimplemented.push(func);
            }
        }
    }

    if !unimplemented.is_empty() {
        // Report error on the contract definition
        let first = &unimplemented[0];

        // Find the contract span (the word "contract" + name)
        let (contract_line, contract_col) = offset_to_line_col(&contract.content, contract.span.start);

        let mut notes = Vec::new();
        for func in &unimplemented {
            let fname = func.name.as_deref().unwrap_or("");
            notes.push(NoteSpan {
                message: format!("unimplemented function `{}` defined in `{}`", fname, contract.name),
                file: contract.file.clone(),
                content: contract.content.clone(),
                span: func.span,
            });
        }

        errors.push(AnalysisError {
            message: format!("contract `{}` has unimplemented functions", contract.name),
            severity: "error".to_string(),
            code: Some("3656".to_string()),
            file: contract.file.clone(),
            content: contract.content.clone(),
            span: contract.name_span,
            notes,
            help: Some("mark the contract as abstract: `abstract contract`".to_string()),
        });
    }
}

fn find_contract_name_span(content: &str, name: &str, contract_start: usize) -> (usize, usize) {
    // Search for the name after the contract start
    let search_in = &content[contract_start..];
    if let Some(pos) = search_in.find(name) {
        let abs_start = contract_start + pos;
        let abs_end = abs_start + name.len();
        (abs_start, abs_end)
    } else {
        (contract_start, contract_start + name.len())
    }
}

// Helper for generating type strings
pub fn type_to_abi_str(ty: &TypeName) -> String {
    match ty {
        TypeName::Elementary(e) => elementary_to_abi_str(e),
        TypeName::Array(inner, size) => {
            let inner_str = type_to_abi_str(inner);
            match size {
                None => format!("{}[]", inner_str),
                Some(e) => match e.as_ref() {
                    Expression::Literal(n) => format!("{}[{}]", inner_str, n.trim()),
                    _ => format!("{}[]", inner_str),
                }
            }
        }
        TypeName::Mapping(k, v) => {
            format!("mapping({} => {})", type_to_abi_str(k), type_to_abi_str(v))
        }
        TypeName::UserDefined(path) => path.join("."),
        TypeName::Function(_, _) => "function".to_string(),
    }
}

pub fn elementary_to_abi_str(e: &ElementaryType) -> String {
    match e {
        ElementaryType::Address(_) => "address".to_string(),
        ElementaryType::Bool => "bool".to_string(),
        ElementaryType::String => "string".to_string(),
        ElementaryType::Bytes => "bytes".to_string(),
        ElementaryType::FixedBytes(n) => format!("bytes{}", n),
        ElementaryType::Int(n) => format!("int{}", *n as u16 * 8),
        ElementaryType::Uint(n) => format!("uint{}", *n as u16 * 8),
        ElementaryType::Fixed(_, _) => "fixed128x18".to_string(),
        ElementaryType::Ufixed(_, _) => "ufixed128x18".to_string(),
    }
}
