fn event_params_to_json(params: &[AbiEventParam], _pretty: bool, indent: &str) -> String {
    let mut s = String::from("[");
    for (i, p) in params.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&format!("{{\"name\":\"{}\",\"type\":\"{}\",\"indexed\":{},\"internalType\":\"{}\"",
            escape_json(&p.name), escape_json(&p.type_), p.indexed, escape_json(&p.internal_type)));
        if let Some(comps) = &p.components {
            s.push_str(&format!(",\"components\":{}", params_to_json(comps, false, indent)));
        }
        s.push('}');
    }
    s.push(']');
    s
}

fn event_params_to_json_pretty(params: &[AbiEventParam], indent: &str) -> String {
    if params.is_empty() {
        return "[]".to_string();
    }
    let inner = format!("{}  ", indent);
    let mut s = String::from("[\n");
    for (i, p) in params.iter().enumerate() {
        s.push_str(&format!("{}{{\n", inner));
        let inner2 = format!("{}  ", inner);
        s.push_str(&format!("{}\"name\": \"{}\",\n", inner2, escape_json(&p.name)));
        s.push_str(&format!("{}\"type\": \"{}\",\n", inner2, escape_json(&p.type_)));
        s.push_str(&format!("{}\"indexed\": {},\n", inner2, p.indexed));
        s.push_str(&format!("{}\"internalType\": \"{}\"", inner2, escape_json(&p.internal_type)));
        if let Some(comps) = &p.components {
            s.push_str(&format!(",\n{}\"components\": {}", inner2, params_to_json_pretty(comps, &inner2)));
        }
        s.push('\n');
        s.push_str(&format!("{}}}", inner));
        if i + 1 < params.len() { s.push(','); }
        s.push('\n');
    }
    s.push_str(&format!("{}]", indent));
    s
}

fn escape_json(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c => result.push(c),
        }
    }
    result
}
