// ABI generation

use crate::ast::*;
use crate::keccak::keccak256_hex4;

#[derive(Debug, Clone)]
pub struct Output {
    pub contracts: Vec<(String, ContractOutput)>,
    pub version: String,
}

#[derive(Debug, Clone)]
pub struct ContractOutput {
    pub abi: Option<Vec<AbiItem>>,
    pub hashes: Option<Vec<(String, String)>>,
}

#[derive(Debug, Clone)]
pub enum AbiItem {
    Constructor {
        inputs: Vec<AbiParam>,
        state_mutability: String,
    },
    Function {
        name: String,
        inputs: Vec<AbiParam>,
        outputs: Vec<AbiParam>,
        state_mutability: String,
    },
    Event {
        name: String,
        inputs: Vec<AbiEventParam>,
        anonymous: bool,
    },
    Error {
        name: String,
        inputs: Vec<AbiParam>,
    },
    Fallback {
        state_mutability: String,
    },
    Receive {
        state_mutability: String,
    },
}

#[derive(Debug, Clone)]
pub struct AbiParam {
    pub name: String,
    pub type_: String,
    pub internal_type: String,
    pub components: Option<Vec<AbiParam>>,
}

#[derive(Debug, Clone)]
pub struct AbiEventParam {
    pub name: String,
    pub type_: String,
    pub indexed: bool,
    pub internal_type: String,
    pub components: Option<Vec<AbiParam>>,
}

pub fn generate_output(
    sources: &[(String, String, SourceUnit)],
    emit: &[String],
) -> Output {
    let want_abi = emit.contains(&"abi".to_string());
    let want_hashes = emit.contains(&"hashes".to_string());

    // Collect type info for resolving struct types
    let type_ctx = build_type_context(sources);

    let mut contract_outputs: std::collections::BTreeMap<String, ContractOutput> = std::collections::BTreeMap::new();

    for (file, _content, su) in sources {
        for item in &su.items {
            if let SourceUnitItem::ContractDefinition(c) = item {
                let key = format!("{}:{}", file, c.name);

                let abi_items = if want_abi {
                    Some(generate_contract_abi(c, &type_ctx))
                } else {
                    None
                };

                let hashes = if want_hashes {
                    Some(generate_contract_hashes(c, &type_ctx))
                } else {
                    None
                };

                contract_outputs.insert(key, ContractOutput { abi: abi_items, hashes });
            }
        }
    }

    Output {
        contracts: contract_outputs.into_iter().collect(),
        version: "0.1.8".to_string(),
    }
}

struct TypeContext {
    // Map from (file, type_path) to struct/enum/user_type info
    structs: std::collections::HashMap<String, Vec<StructField>>,
    enums: std::collections::HashMap<String, Vec<String>>,
    user_types: std::collections::HashMap<String, ElementaryType>,
}

fn build_type_context(sources: &[(String, String, SourceUnit)]) -> TypeContext {
    let mut ctx = TypeContext {
        structs: std::collections::HashMap::new(),
        enums: std::collections::HashMap::new(),
        user_types: std::collections::HashMap::new(),
    };

    for (file, _content, su) in sources {
        for item in &su.items {
            match item {
                SourceUnitItem::StructDefinition(s) => {
                    ctx.structs.insert(s.name.clone(), s.fields.clone());
                }
                SourceUnitItem::EnumDefinition(e) => {
                    ctx.enums.insert(e.name.clone(), e.values.clone());
                }
                SourceUnitItem::UserDefinedValueType(t) => {
                    ctx.user_types.insert(t.name.clone(), t.underlying.clone());
                }
                SourceUnitItem::ContractDefinition(c) => {
                    // Register contract-level structs/enums with qualified names
                    for ci in &c.items {
                        match ci {
                            ContractItem::StructDefinition(s) => {
                                ctx.structs.insert(format!("{}.{}", c.name, s.name), s.fields.clone());
                                ctx.structs.insert(s.name.clone(), s.fields.clone());
                            }
                            ContractItem::EnumDefinition(e) => {
                                ctx.enums.insert(format!("{}.{}", c.name, e.name), e.values.clone());
                                ctx.enums.insert(e.name.clone(), e.values.clone());
                            }
                            ContractItem::UserDefinedValueType(t) => {
                                ctx.user_types.insert(format!("{}.{}", c.name, t.name), t.underlying.clone());
                                ctx.user_types.insert(t.name.clone(), t.underlying.clone());
                            }
                            _ => {}
                        }
                    }
                }
                _ => {}
            }
        }
    }

    ctx
}

fn generate_contract_abi(contract: &ContractDefinition, ctx: &TypeContext) -> Vec<AbiItem> {
    let mut items = Vec::new();
    let contract_name = &contract.name;

    for ci in &contract.items {
        match ci {
            ContractItem::ConstructorDefinition(f) => {
                let mutability = mutability_to_str(&f.mutability);
                items.push(AbiItem::Constructor {
                    inputs: params_to_abi(&f.params, ctx),
                    state_mutability: mutability,
                });
            }
            ContractItem::FallbackDefinition(f) => {
                let mutability = mutability_to_str(&f.mutability);
                items.push(AbiItem::Fallback { state_mutability: mutability });
            }
            ContractItem::ReceiveDefinition(f) => {
                let mutability = mutability_to_str(&f.mutability);
                items.push(AbiItem::Receive { state_mutability: mutability });
            }
            ContractItem::FunctionDefinition(f) => {
                if f.visibility == Visibility::Public || f.visibility == Visibility::External {
                    let name = f.name.clone().unwrap_or_default();
                    let mutability = mutability_to_str(&f.mutability);
                    items.push(AbiItem::Function {
                        name,
                        inputs: params_to_abi(&f.params, ctx),
                        outputs: params_to_abi(&f.return_params, ctx),
                        state_mutability: mutability,
                    });
                }
            }
            ContractItem::StateVariableDeclaration(sv) => {
                if sv.visibility == Visibility::Public {
                    // Generate getter function
                    let (inputs, outputs) = generate_getter_params(&sv.type_, &sv.name, ctx);
                    items.push(AbiItem::Function {
                        name: sv.name.clone(),
                        inputs,
                        outputs,
                        state_mutability: "view".to_string(),
                    });
                }
            }
            ContractItem::EventDefinition(e) => {
                items.push(AbiItem::Event {
                    name: e.name.clone(),
                    inputs: event_params_to_abi(&e.params, ctx),
                    anonymous: e.anonymous,
                });
            }
            ContractItem::ErrorDefinition(e) => {
                items.push(AbiItem::Error {
                    name: e.name.clone(),
                    inputs: params_to_abi(&e.params, ctx),
                });
            }
            _ => {}
        }
    }

    // Sort: constructor first, then by type name, then by item name
    items.sort_by(|a, b| {
        let type_order = |item: &AbiItem| match item {
            AbiItem::Constructor { .. } => 0,
            AbiItem::Error { .. } => 1,
            AbiItem::Event { .. } => 2,
            AbiItem::Fallback { .. } => 3,
            AbiItem::Function { .. } => 4,
            AbiItem::Receive { .. } => 5,
        };

        let ta = type_order(a);
        let tb = type_order(b);

        if ta != tb {
            return ta.cmp(&tb);
        }

        // Same type, sort by name
        let name_a = match a {
            AbiItem::Function { name, .. } => name.as_str(),
            AbiItem::Event { name, .. } => name.as_str(),
            AbiItem::Error { name, .. } => name.as_str(),
            _ => "",
        };
        let name_b = match b {
            AbiItem::Function { name, .. } => name.as_str(),
            AbiItem::Event { name, .. } => name.as_str(),
            AbiItem::Error { name, .. } => name.as_str(),
            _ => "",
        };

        name_a.cmp(name_b)
    });

    items
}

fn generate_contract_hashes(contract: &ContractDefinition, ctx: &TypeContext) -> Vec<(String, String)> {
    let mut hashes = Vec::new();

    for ci in &contract.items {
        match ci {
            ContractItem::FunctionDefinition(f) => {
                if f.visibility == Visibility::Public || f.visibility == Visibility::External {
                    if let Some(name) = &f.name {
                        let sig = generate_function_signature(name, &f.params, ctx);
                        let hash = keccak256_hex4(sig.as_bytes());
                        hashes.push((sig, hash));
                    }
                }
            }
            ContractItem::StateVariableDeclaration(sv) => {
                if sv.visibility == Visibility::Public {
                    let (inputs, _) = generate_getter_params(&sv.type_, &sv.name, ctx);
                    let input_types: Vec<String> = inputs.iter().map(|p| p.type_.clone()).collect();
                    let sig = format!("{}({})", sv.name, input_types.join(","));
                    let hash = keccak256_hex4(sig.as_bytes());
                    hashes.push((sig, hash));
                }
            }
            _ => {}
        }
    }

    hashes.sort_by(|a, b| a.0.cmp(&b.0));
    hashes
}

fn generate_function_signature(name: &str, params: &[Parameter], ctx: &TypeContext) -> String {
    let param_types: Vec<String> = params.iter().map(|p| type_to_abi_canonical(&p.type_, ctx)).collect();
    format!("{}({})", name, param_types.join(","))
}

fn type_to_abi_canonical(ty: &TypeName, ctx: &TypeContext) -> String {
    match ty {
        TypeName::Elementary(e) => elementary_to_abi(e),
        TypeName::Array(inner, size) => {
            let inner_str = type_to_abi_canonical(inner, ctx);
            match size {
                None => format!("{}[]", inner_str),
                Some(e) => match e.as_ref() {
                    Expression::Literal(n) => format!("{}[{}]", inner_str, n.trim()),
                    _ => format!("{}[]", inner_str),
                }
            }
        }
        TypeName::Mapping(_, _) => "mapping".to_string(),
        TypeName::UserDefined(path) => {
            let type_name = path.last().cloned().unwrap_or_default();
            let full_name = path.join(".");

            // Check if it's a struct
            if let Some(fields) = ctx.structs.get(&full_name).or_else(|| ctx.structs.get(&type_name)) {
                let field_types: Vec<String> = fields.iter()
                    .map(|f| type_to_abi_canonical(&f.type_, ctx))
                    .collect();
                return format!("({})", field_types.join(","));
            }

            // Check if it's an enum
            if ctx.enums.contains_key(&full_name) || ctx.enums.contains_key(&type_name) {
                return "uint8".to_string();
            }

            // Check if it's a user-defined value type
            if let Some(underlying) = ctx.user_types.get(&full_name).or_else(|| ctx.user_types.get(&type_name)) {
                return elementary_to_abi(underlying);
            }

            // Default fallback
            type_name
        }
        TypeName::Function(_, _) => "function".to_string(),
    }
}

fn params_to_abi(params: &[Parameter], ctx: &TypeContext) -> Vec<AbiParam> {
    params.iter().map(|p| param_to_abi(p, ctx)).collect()
}

fn param_to_abi(param: &Parameter, ctx: &TypeContext) -> AbiParam {
    let (type_str, internal_type, components) = type_to_abi_info(&param.type_, ctx, None);
    AbiParam {
        name: param.name.clone().unwrap_or_default(),
        type_: type_str,
        internal_type,
        components,
    }
}

fn event_params_to_abi(params: &[EventParameter], ctx: &TypeContext) -> Vec<AbiEventParam> {
    params.iter().map(|p| {
        let (type_str, internal_type, components) = type_to_abi_info(&p.type_, ctx, None);
        AbiEventParam {
            name: p.name.clone().unwrap_or_default(),
            type_: type_str,
            indexed: p.indexed,
            internal_type,
            components,
        }
    }).collect()
}

fn type_to_abi_info(ty: &TypeName, ctx: &TypeContext, parent_contract: Option<&str>) -> (String, String, Option<Vec<AbiParam>>) {
    match ty {
        TypeName::Elementary(e) => {
            let abi_str = elementary_to_abi(e);
            let internal = elementary_internal_type(e);
            (abi_str, internal, None)
        }
        TypeName::Array(inner, size) => {
            let (inner_type, inner_internal, inner_components) = type_to_abi_info(inner, ctx, parent_contract);
            let suffix = match size {
                None => "[]".to_string(),
                Some(e) => match e.as_ref() {
                    Expression::Literal(n) => format!("[{}]", n.trim()),
                    _ => "[]".to_string(),
                }
            };
            let type_str = format!("{}{}", inner_type, suffix);
            let internal_str = format!("{}{}", inner_internal, suffix);

            // Components for array of tuples
            let components = if inner_type == "tuple" { inner_components } else { None };

            (type_str, internal_str, components)
        }
        TypeName::UserDefined(path) => {
            let type_name = path.last().cloned().unwrap_or_default();
            let full_name = path.join(".");

            // Check struct
            if let Some(fields) = ctx.structs.get(&full_name).or_else(|| ctx.structs.get(&type_name)) {
                let internal_type = format!("struct {}", full_name);
                let components: Vec<AbiParam> = fields.iter().map(|f| {
                    let (ft, fi, fc) = type_to_abi_info(&f.type_, ctx, parent_contract);
                    AbiParam {
                        name: f.name.clone(),
                        type_: ft,
                        internal_type: fi,
                        components: fc,
                    }
                }).collect();
                return ("tuple".to_string(), internal_type, Some(components));
            }

            // Check enum
            if ctx.enums.contains_key(&full_name) || ctx.enums.contains_key(&type_name) {
                let internal_type = format!("enum {}", full_name);
                return ("uint8".to_string(), internal_type, None);
            }

            // Check user-defined value type
            if let Some(underlying) = ctx.user_types.get(&full_name).or_else(|| ctx.user_types.get(&type_name)) {
                let abi_str = elementary_to_abi(underlying);
                return (abi_str, full_name.clone(), None);
            }

            // Unknown - use as-is
            (type_name.clone(), type_name.clone(), None)
        }
        TypeName::Mapping(key, value) => {
            // Mappings in ABI - should not appear normally
            ("mapping".to_string(), "mapping".to_string(), None)
        }
        TypeName::Function(_, _) => {
            ("function".to_string(), "function".to_string(), None)
        }
    }
}

fn elementary_to_abi(e: &ElementaryType) -> String {
    match e {
        ElementaryType::Address(_) => "address".to_string(),
        ElementaryType::Bool => "bool".to_string(),
        ElementaryType::String => "string".to_string(),
        ElementaryType::Bytes => "bytes".to_string(),
        ElementaryType::FixedBytes(n) => format!("bytes{}", n),
        ElementaryType::Int(n) => {
            let bits = (*n as u16) * 8;
            format!("int{}", bits)
        }
        ElementaryType::Uint(n) => {
            let bits = (*n as u16) * 8;
            format!("uint{}", bits)
        }
        ElementaryType::Fixed(_, _) => "fixed128x18".to_string(),
        ElementaryType::Ufixed(_, _) => "ufixed128x18".to_string(),
    }
}

fn elementary_internal_type(e: &ElementaryType) -> String {
    match e {
        ElementaryType::Address(true) => "address payable".to_string(),
        ElementaryType::Address(false) => "address".to_string(),
        _ => elementary_to_abi(e),
    }
}

fn mutability_to_str(m: &Mutability) -> String {
    match m {
        Mutability::Pure => "pure".to_string(),
        Mutability::View => "view".to_string(),
        Mutability::Payable => "payable".to_string(),
        Mutability::NonPayable => "nonpayable".to_string(),
    }
}

fn generate_getter_params(ty: &TypeName, _name: &str, ctx: &TypeContext) -> (Vec<AbiParam>, Vec<AbiParam>) {
    // For a mapping(k => v), the getter takes k and returns generate_getter_params(v)
    // For an array T[], getter takes uint256 index and returns T
    // For elementary/struct, getter takes nothing and returns the type
    generate_getter_params_inner(ty, ctx)
}

fn generate_getter_params_inner(ty: &TypeName, ctx: &TypeContext) -> (Vec<AbiParam>, Vec<AbiParam>) {
    match ty {
        TypeName::Mapping(key, value) => {
            let (key_type, key_internal, _) = type_to_abi_info(key, ctx, None);
            let key_param = AbiParam {
                name: "".to_string(),
                type_: key_type,
                internal_type: key_internal,
                components: None,
            };
            let (mut inner_inputs, outputs) = generate_getter_params_inner(value, ctx);
            let mut inputs = vec![key_param];
            inputs.append(&mut inner_inputs);
            (inputs, outputs)
        }
        TypeName::Array(inner, _) => {
            let index_param = AbiParam {
                name: "".to_string(),
                type_: "uint256".to_string(),
                internal_type: "uint256".to_string(),
                components: None,
            };
            let (inner_type, inner_internal, components) = type_to_abi_info(inner, ctx, None);
            let output = AbiParam {
                name: "".to_string(),
                type_: inner_type,
                internal_type: inner_internal,
                components,
            };
            (vec![index_param], vec![output])
        }
        _ => {
            let (type_str, internal_type, components) = type_to_abi_info(ty, ctx, None);
            let output = AbiParam {
                name: "".to_string(),
                type_: type_str,
                internal_type,
                components,
            };
            (Vec::new(), vec![output])
        }
    }
}

impl Output {
    pub fn to_json(&self) -> String {
        let mut s = String::new();
        s.push_str("{\"contracts\":{");

        let mut first_contract = true;
        for (key, contract_out) in &self.contracts {
            if !first_contract { s.push(','); }
            first_contract = false;

            s.push('"');
            s.push_str(&escape_json(key));
            s.push_str("\":{");

            let mut first_field = true;

            if let Some(abi) = &contract_out.abi {
                if !first_field { s.push(','); }
                first_field = false;
                s.push_str("\"abi\":");
                s.push_str(&abi_items_to_json(abi, false));
            }

            if let Some(hashes) = &contract_out.hashes {
                if !first_field { s.push(','); }
                first_field = false;
                s.push_str("\"hashes\":{");
                let mut fh = true;
                for (sig, hash) in hashes {
                    if !fh { s.push(','); }
                    fh = false;
                    s.push('"');
                    s.push_str(&escape_json(sig));
                    s.push_str("\":\"");
                    s.push_str(hash);
                    s.push('"');
                }
                s.push('}');
            }

            s.push('}');
        }

        s.push_str("},\"version\":\"0.1.8\"}");
        s
    }

    pub fn to_pretty_json(&self) -> String {
        let mut s = String::new();
        s.push_str("{\n  \"contracts\": {\n");

        let contracts: Vec<_> = self.contracts.iter().collect();
        for (i, (key, contract_out)) in contracts.iter().enumerate() {
            s.push_str(&format!("    \"{}\": {{\n", escape_json(key)));

            let mut fields = Vec::new();

            if let Some(abi) = &contract_out.abi {
                fields.push(format!("      \"abi\": {}", abi_items_to_json_pretty(abi, "      ")));
            }

            if let Some(hashes) = &contract_out.hashes {
                let mut h = String::new();
                h.push_str("{\n");
                for (j, (sig, hash)) in hashes.iter().enumerate() {
                    h.push_str(&format!("          \"{}\": \"{}\"", escape_json(sig), hash));
                    if j + 1 < hashes.len() { h.push(','); }
                    h.push('\n');
                }
                h.push_str("        }");
                fields.push(format!("      \"hashes\": {}", h));
            }

            for (j, field) in fields.iter().enumerate() {
                s.push_str(field);
                if j + 1 < fields.len() { s.push(','); }
                s.push('\n');
            }

            s.push_str("    }");
            if i + 1 < contracts.len() { s.push(','); }
            s.push('\n');
        }

        s.push_str("  },\n");
        s.push_str("  \"version\": \"0.1.8\"\n");
        s.push('}');
        s
    }
}

fn abi_items_to_json(items: &[AbiItem], _pretty: bool) -> String {
    let mut s = String::from("[");
    for (i, item) in items.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&abi_item_to_json(item, false, ""));
    }
    s.push(']');
    s
}

fn abi_items_to_json_pretty(items: &[AbiItem], indent: &str) -> String {
    if items.is_empty() {
        return "[]".to_string();
    }

    let inner_indent = format!("{}  ", indent);
    let mut s = String::from("[\n");
    for (i, item) in items.iter().enumerate() {
        s.push_str(&abi_item_to_json_pretty(item, &inner_indent));
        if i + 1 < items.len() { s.push(','); }
        s.push('\n');
    }
    s.push_str(&format!("{}]", indent));
    s
}

fn abi_item_to_json(item: &AbiItem, _pretty: bool, indent: &str) -> String {
    match item {
        AbiItem::Constructor { inputs, state_mutability } => {
            format!("{{\"type\":\"constructor\",\"inputs\":{},\"stateMutability\":\"{}\"}}",
                params_to_json(inputs, false, ""), state_mutability)
        }
        AbiItem::Function { name, inputs, outputs, state_mutability } => {
            format!("{{\"type\":\"function\",\"name\":\"{}\",\"inputs\":{},\"outputs\":{},\"stateMutability\":\"{}\"}}",
                escape_json(name),
                params_to_json(inputs, false, ""),
                params_to_json(outputs, false, ""),
                state_mutability)
        }
        AbiItem::Event { name, inputs, anonymous } => {
            format!("{{\"type\":\"event\",\"name\":\"{}\",\"inputs\":{},\"anonymous\":{}}}",
                escape_json(name),
                event_params_to_json(inputs, false, ""),
                anonymous)
        }
        AbiItem::Error { name, inputs } => {
            format!("{{\"type\":\"error\",\"name\":\"{}\",\"inputs\":{}}}",
                escape_json(name),
                params_to_json(inputs, false, ""))
        }
        AbiItem::Fallback { state_mutability } => {
            format!("{{\"type\":\"fallback\",\"stateMutability\":\"{}\"}}", state_mutability)
        }
        AbiItem::Receive { state_mutability } => {
            format!("{{\"type\":\"receive\",\"stateMutability\":\"{}\"}}", state_mutability)
        }
    }
}

fn abi_item_to_json_pretty(item: &AbiItem, indent: &str) -> String {
    let inner = format!("{}  ", indent);
    match item {
        AbiItem::Constructor { inputs, state_mutability } => {
            format!("{}{{\n{}\"type\": \"constructor\",\n{}\"inputs\": {},\n{}\"stateMutability\": \"{}\"\n{}}}",
                indent,
                inner, inner, params_to_json_pretty(inputs, &inner),
                inner, state_mutability,
                indent)
        }
        AbiItem::Function { name, inputs, outputs, state_mutability } => {
            format!("{}{{\n{}\"type\": \"function\",\n{}\"name\": \"{}\",\n{}\"inputs\": {},\n{}\"outputs\": {},\n{}\"stateMutability\": \"{}\"\n{}}}",
                indent,
                inner, inner, escape_json(name),
                inner, params_to_json_pretty(inputs, &inner),
                inner, params_to_json_pretty(outputs, &inner),
                inner, state_mutability,
                indent)
        }
        AbiItem::Event { name, inputs, anonymous } => {
            format!("{}{{\n{}\"type\": \"event\",\n{}\"name\": \"{}\",\n{}\"inputs\": {},\n{}\"anonymous\": {}\n{}}}",
                indent,
                inner, inner, escape_json(name),
                inner, event_params_to_json_pretty(inputs, &inner),
                inner, anonymous,
                indent)
        }
        AbiItem::Error { name, inputs } => {
            format!("{}{{\n{}\"type\": \"error\",\n{}\"name\": \"{}\",\n{}\"inputs\": {}\n{}}}",
                indent,
                inner, inner, escape_json(name),
                inner, params_to_json_pretty(inputs, &inner),
                indent)
        }
        AbiItem::Fallback { state_mutability } => {
            format!("{}{{\n{}\"type\": \"fallback\",\n{}\"stateMutability\": \"{}\"\n{}}}",
                indent, inner, inner, state_mutability, indent)
        }
        AbiItem::Receive { state_mutability } => {
            format!("{}{{\n{}\"type\": \"receive\",\n{}\"stateMutability\": \"{}\"\n{}}}",
                indent, inner, inner, state_mutability, indent)
        }
    }
}

fn params_to_json(params: &[AbiParam], _pretty: bool, indent: &str) -> String {
    let mut s = String::from("[");
    for (i, p) in params.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&param_to_json(p, false, indent));
    }
    s.push(']');
    s
}

fn params_to_json_pretty(params: &[AbiParam], indent: &str) -> String {
    if params.is_empty() {
        return "[]".to_string();
    }
    let inner = format!("{}  ", indent);
    let mut s = String::from("[\n");
    for (i, p) in params.iter().enumerate() {
        s.push_str(&param_to_json_pretty(p, &inner));
        if i + 1 < params.len() { s.push(','); }
        s.push('\n');
    }
    s.push_str(&format!("{}]", indent));
    s
}

fn param_to_json(p: &AbiParam, _pretty: bool, indent: &str) -> String {
    let mut s = String::from("{");
    s.push_str(&format!("\"name\":\"{}\",\"type\":\"{}\",\"internalType\":\"{}\"",
        escape_json(&p.name), escape_json(&p.type_), escape_json(&p.internal_type)));
    if let Some(comps) = &p.components {
        s.push_str(&format!(",\"components\":{}", params_to_json(comps, false, indent)));
    }
    s.push('}');
    s
}

fn param_to_json_pretty(p: &AbiParam, indent: &str) -> String {
    let inner = format!("{}  ", indent);
    let mut s = String::new();
    s.push_str(&format!("{}{{\n", indent));
    s.push_str(&format!("{}\"name\": \"{}\",\n", inner, escape_json(&p.name)));
    s.push_str(&format!("{}\"type\": \"{}\",\n", inner, escape_json(&p.type_)));
    s.push_str(&format!("{}\"internalType\": \"{}\"", inner, escape_json(&p.internal_type)));
    if let Some(comps) = &p.components {
        s.push_str(&format!(",\n{}\"components\": {}", inner, params_to_json_pretty(comps, &inner)));
    }
    s.push('\n');
    s.push_str(&format!("{}}}", indent));
    s
}

fn event_params_to_json(params: &[AbiEventParam], _pretty: bool, indent: &str) -> String {
    let mut s = String::from("[");
    for (i, p) in params.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&format!("{{\"name\":\"{}\",\"type\":\"{}\",\"indexed\":{},\"internalType\":\"{}\"",
            escape_json(&p.name), escape_json(&p.type_), p.indexed, escape_json(&p.internal_type)));
        if let Some(comps) = &p.components {
            s.push_str(&format!(",\"components\":{}", params_to_json(comps, false, indent)));
        }
        s.push('}');
    }
    s.push(']');
    s
}

fn event_params_to_json_pretty(params: &[AbiEventParam], indent: &str) -> String {
    if params.is_empty() {
        return "[]".to_string();
    }
    let inner = format!("{}  ", indent);
    let mut s = String::from("[\n");
    for (i, p) in params.iter().enumerate() {
        s.push_str(&format!("{}{{\n", inner));
        let inner2 = format!("{}  ", inner);
        s.push_str(&format!("{}\"name\": \"{}\",\n", inner2, escape_json(&p.name)));
        s.push_str(&format!("{}\"type\": \"{}\",\n", inner2, escape_json(&p.type_)));
        s.push_str(&format!("{}\"indexed\": {},\n", inner2, p.indexed));
        s.push_str(&format!("{}\"internalType\": \"{}\"", inner2, escape_json(&p.internal_type)));
        if let Some(comps) = &p.components {
            s.push_str(&format!(",\n{}\"components\": {}", inner2, params_to_json_pretty(comps, &inner2)));
        }
        s.push('\n');
        s.push_str(&format!("{}}}", inner));
        if i + 1 < params.len() { s.push(','); }
        s.push('\n');
    }
    s.push_str(&format!("{}]", indent));
    s
}

fn escape_json(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c => result.push(c),
        }
    }
    result
}
