// Statement parsing (for function bodies, to detect syntax errors)

impl<'a> Parser<'a> {
    pub fn parse_block(&mut self) -> Result<(), ParseError> {
        self.expect(&TokenKind::LBrace)?;

        while !self.at_eof() && self.current().kind != TokenKind::RBrace {
            match self.parse_statement() {
                Ok(()) => {}
                Err(e) => {
                    return Err(e);
                }
            }
        }

        self.expect(&TokenKind::RBrace)?;
        Ok(())
    }

    fn parse_statement(&mut self) -> Result<(), ParseError> {
        match self.current().kind.clone() {
            TokenKind::LBrace => {
                self.parse_block()?;
            }
            TokenKind::If => {
                self.advance(); // if
                self.expect(&TokenKind::LParen)?;
                self.parse_expr()?;
                self.expect(&TokenKind::RParen)?;
                self.parse_statement()?;
                if self.current().kind == TokenKind::Else {
                    self.advance();
                    self.parse_statement()?;
                }
            }
            TokenKind::While => {
                self.advance();
                self.expect(&TokenKind::LParen)?;
                self.parse_expr()?;
                self.expect(&TokenKind::RParen)?;
                self.parse_statement()?;
            }
            TokenKind::Do => {
                self.advance();
                self.parse_statement()?;
                self.expect(&TokenKind::While)?;
                self.expect(&TokenKind::LParen)?;
                self.parse_expr()?;
                self.expect(&TokenKind::RParen)?;
                self.eat(&TokenKind::Semicolon);
            }
            TokenKind::For_ => {
                self.advance();
                self.expect(&TokenKind::LParen)?;
                // init
                if self.current().kind != TokenKind::Semicolon {
                    if self.is_var_decl_start() {
                        self.parse_var_decl_stmt()?;
                    } else {
                        self.parse_expr()?;
                        self.eat(&TokenKind::Semicolon);
                    }
                } else {
                    self.advance(); // ;
                }
                // condition
                if self.current().kind != TokenKind::Semicolon {
                    self.parse_expr()?;
                }
                self.eat(&TokenKind::Semicolon);
                // increment
                if self.current().kind != TokenKind::RParen {
                    self.parse_expr()?;
                }
                self.expect(&TokenKind::RParen)?;
                self.parse_statement()?;
            }
            TokenKind::Return => {
                self.advance();
                if self.current().kind != TokenKind::Semicolon {
                    self.parse_expr()?;
                }
                self.eat(&TokenKind::Semicolon);
            }
            TokenKind::Emit => {
                self.advance();
                let (_, _) = self.expect_identifier()?;
                while self.eat(&TokenKind::Dot) {
                    self.expect_identifier()?;
                }
                self.expect(&TokenKind::LParen)?;
                self.skip_to_closing_paren()?;
                self.eat(&TokenKind::Semicolon);
            }
            TokenKind::Revert => {
                self.advance();
                // Optional error name
                if matches!(self.current().kind, TokenKind::Identifier(_)) {
                    self.advance();
                    while self.eat(&TokenKind::Dot) {
                        self.expect_identifier()?;
                    }
                }
                if self.current().kind == TokenKind::LParen {
                    self.skip_parens();
                }
                self.eat(&TokenKind::Semicolon);
            }
            TokenKind::Break | TokenKind::Continue => {
                self.advance();
                self.eat(&TokenKind::Semicolon);
            }
            TokenKind::Semicolon => {
                self.advance();
            }
            TokenKind::Assembly => {
                self.advance();
                // Optional "evmasm"
                if matches!(self.current().kind, TokenKind::StringLiteral(_)) {
                    self.advance();
                }
                // skip the assembly block
                self.skip_block();
            }
            TokenKind::Unchecked => {
                self.advance();
                self.parse_block()?;
            }
            TokenKind::Try => {
                self.advance();
                self.parse_expr()?;
                if self.eat(&TokenKind::Returns) {
                    self.expect(&TokenKind::LParen)?;
                    while !self.at_eof() && self.current().kind != TokenKind::RParen {
                        self.parse_parameter()?;
                        if !self.eat(&TokenKind::Comma) { break; }
                    }
                    self.expect(&TokenKind::RParen)?;
                }
                self.parse_block()?;
                while self.current().kind == TokenKind::Catch {
                    self.advance();
                    if matches!(self.current().kind, TokenKind::Identifier(_)) {
                        self.advance();
                    }
                    if self.current().kind == TokenKind::LParen {
                        self.skip_parens();
                    }
                    self.parse_block()?;
                }
            }
            TokenKind::Delete => {
                self.advance();
                self.parse_expr()?;
                self.eat(&TokenKind::Semicolon);
            }
            _ => {
                // Variable declaration or expression statement
                // Tricky: "uint x = ..." vs "x = ..."
                if self.is_var_decl_start() {
                    self.parse_var_decl_stmt()?;
                } else {
                    self.parse_expr()?;
                    self.eat(&TokenKind::Semicolon);
                }
            }
        }
        Ok(())
    }

    fn parse_var_decl_stmt(&mut self) -> Result<(), ParseError> {
        // Could be: type [memory|storage|calldata] [name] [= expr] [;]
        // Or tuple: (type1 name1, type2 name2) = expr;
        if self.current().kind == TokenKind::LParen {
            // Tuple destructuring
            self.skip_parens();
            if self.eat(&TokenKind::Eq) {
                self.parse_expr()?;
            }
            self.eat(&TokenKind::Semicolon);
            return Ok(());
        }

        let _type = self.parse_type()?;

        // Location
        match self.current().kind {
            TokenKind::Memory | TokenKind::Storage | TokenKind::Calldata => { self.advance(); }
            _ => {}
        }

        // Name (optional)
        match self.current().kind.clone() {
            TokenKind::Identifier(_) => { self.advance(); }
            _ if is_keyword_usable_as_identifier(&self.current().kind) => { self.advance(); }
            _ => {}
        }

        // Assignment (optional, but might be required)
        if self.eat(&TokenKind::Eq) {
            self.parse_expr()?;
        } else if self.current().kind != TokenKind::Semicolon && self.current().kind != TokenKind::RBrace {
            // Check if it's a tuple like (uint a, uint b) = ...  
            // or just missing semicolon
        }

        self.eat(&TokenKind::Semicolon);
        Ok(())
    }

    fn is_var_decl_start(&self) -> bool {
        // Type keywords that unambiguously start a declaration
        matches!(self.current().kind,
            TokenKind::Address | TokenKind::Bool | TokenKind::String_ | 
            TokenKind::Bytes | TokenKind::Bytes_(_) | TokenKind::Int(_) | 
            TokenKind::Uint(_) | TokenKind::Fixed | TokenKind::Ufixed |
            TokenKind::Mapping
        )
    }

    fn parse_expr(&mut self) -> Result<(), ParseError> {
        self.parse_assignment_expr()
    }

    fn parse_assignment_expr(&mut self) -> Result<(), ParseError> {
        self.parse_ternary_expr()?;

        // Assignment operators
        match self.current().kind {
            TokenKind::Eq | TokenKind::PlusEq | TokenKind::MinusEq | 
            TokenKind::StarEq | TokenKind::SlashEq | TokenKind::PercentEq => {
                self.advance();
                self.parse_ternary_expr()?;
            }
            _ => {}
        }

        Ok(())
    }

    fn parse_ternary_expr(&mut self) -> Result<(), ParseError> {
        self.parse_or_expr()?;
        if self.eat(&TokenKind::Question) {
            self.parse_expr()?;
            self.expect(&TokenKind::Colon)?;
            self.parse_ternary_expr()?;
        }
        Ok(())
    }

    fn parse_or_expr(&mut self) -> Result<(), ParseError> {
        self.parse_and_expr()?;
        while self.eat(&TokenKind::OrOr) {
            self.parse_and_expr()?;
        }
        Ok(())
    }

    fn parse_and_expr(&mut self) -> Result<(), ParseError> {
        self.parse_bitwise_or()?;
        while self.eat(&TokenKind::AndAnd) {
            self.parse_bitwise_or()?;
        }
        Ok(())
    }

    fn parse_bitwise_or(&mut self) -> Result<(), ParseError> {
        self.parse_bitwise_xor()?;
        while self.eat(&TokenKind::Or) {
            self.parse_bitwise_xor()?;
        }
        Ok(())
    }

    fn parse_bitwise_xor(&mut self) -> Result<(), ParseError> {
        self.parse_bitwise_and()?;
        while self.eat(&TokenKind::Caret) {
            self.parse_bitwise_and()?;
        }
        Ok(())
    }

    fn parse_bitwise_and(&mut self) -> Result<(), ParseError> {
        self.parse_equality()?;
        while self.eat(&TokenKind::And) {
            self.parse_equality()?;
        }
        Ok(())
    }

    fn parse_equality(&mut self) -> Result<(), ParseError> {
        self.parse_comparison()?;
        while matches!(self.current().kind, TokenKind::EqEq | TokenKind::BangEq) {
            self.advance();
            self.parse_comparison()?;
        }
        Ok(())
    }

    fn parse_comparison(&mut self) -> Result<(), ParseError> {
        self.parse_shift()?;
        while matches!(self.current().kind, TokenKind::Lt | TokenKind::LtEq | TokenKind::Gt | TokenKind::GtEq) {
            self.advance();
            self.parse_shift()?;
        }
        Ok(())
    }

    fn parse_shift(&mut self) -> Result<(), ParseError> {
        self.parse_additive()?;
        while matches!(self.current().kind, TokenKind::LtLt | TokenKind::GtGt) {
            self.advance();
            self.parse_additive()?;
        }
        Ok(())
    }

    fn parse_additive(&mut self) -> Result<(), ParseError> {
        self.parse_multiplicative()?;
        while matches!(self.current().kind, TokenKind::Plus | TokenKind::Minus) {
            self.advance();
            self.parse_multiplicative()?;
        }
        Ok(())
    }

    fn parse_multiplicative(&mut self) -> Result<(), ParseError> {
        self.parse_exponentiation()?;
        while matches!(self.current().kind, TokenKind::Star | TokenKind::Slash | TokenKind::Percent) {
            self.advance();
            self.parse_exponentiation()?;
        }
        Ok(())
    }

    fn parse_exponentiation(&mut self) -> Result<(), ParseError> {
        self.parse_unary()?;
        if self.eat(&TokenKind::StarStar) {
            self.parse_unary()?;
        }
        Ok(())
    }

    fn parse_unary(&mut self) -> Result<(), ParseError> {
        match self.current().kind.clone() {
            TokenKind::Not | TokenKind::Tilde | TokenKind::Minus | TokenKind::Plus => {
                self.advance();
                self.parse_unary()?;
            }
            TokenKind::PlusPlus | TokenKind::MinusMinus => {
