    fn parse_bitwise_and(&mut self) -> Result<(), ParseError> {
        self.parse_equality()?;
        while self.eat(&TokenKind::And) {
            self.parse_equality()?;
        }
        Ok(())
    }

    fn parse_equality(&mut self) -> Result<(), ParseError> {
        self.parse_comparison()?;
        while matches!(self.current().kind, TokenKind::EqEq | TokenKind::BangEq) {
            self.advance();
            self.parse_comparison()?;
        }
        Ok(())
    }

    fn parse_comparison(&mut self) -> Result<(), ParseError> {
        self.parse_shift()?;
        while matches!(self.current().kind, TokenKind::Lt | TokenKind::LtEq | TokenKind::Gt | TokenKind::GtEq) {
            self.advance();
            self.parse_shift()?;
        }
        Ok(())
    }

    fn parse_shift(&mut self) -> Result<(), ParseError> {
        self.parse_additive()?;
        while matches!(self.current().kind, TokenKind::LtLt | TokenKind::GtGt) {
            self.advance();
            self.parse_additive()?;
        }
        Ok(())
    }

    fn parse_additive(&mut self) -> Result<(), ParseError> {
        self.parse_multiplicative()?;
        while matches!(self.current().kind, TokenKind::Plus | TokenKind::Minus) {
            self.advance();
            self.parse_multiplicative()?;
        }
        Ok(())
    }

    fn parse_multiplicative(&mut self) -> Result<(), ParseError> {
        self.parse_exponentiation()?;
        while matches!(self.current().kind, TokenKind::Star | TokenKind::Slash | TokenKind::Percent) {
            self.advance();
            self.parse_exponentiation()?;
        }
        Ok(())
    }

    fn parse_exponentiation(&mut self) -> Result<(), ParseError> {
        self.parse_unary()?;
        if self.eat(&TokenKind::StarStar) {
            self.parse_unary()?;
        }
        Ok(())
    }

    fn parse_unary(&mut self) -> Result<(), ParseError> {
        match self.current().kind.clone() {
            TokenKind::Not | TokenKind::Tilde | TokenKind::Minus | TokenKind::Plus => {
                self.advance();
                self.parse_unary()?;
            }
            TokenKind::PlusPlus | TokenKind::MinusMinus => {
                self.advance();
                self.parse_unary()?;
            }
            TokenKind::Delete => {
                self.advance();
                self.parse_unary()?;
            }
            _ => {
                self.parse_postfix()?;
            }
        }
        Ok(())
    }

    fn parse_postfix(&mut self) -> Result<(), ParseError> {
        self.parse_primary()?;
        loop {
            match self.current().kind.clone() {
                TokenKind::PlusPlus | TokenKind::MinusMinus => {
                    self.advance();
                }
                TokenKind::Dot => {
                    self.advance();
                    // identifier or 'address' etc  
                    match self.current().kind.clone() {
                        TokenKind::Identifier(_) => { self.advance(); }
                        _ if is_keyword_usable_as_identifier(&self.current().kind) => { self.advance(); }
                        TokenKind::Address => { self.advance(); } // address member
                        _ => {
                            let cur = self.current().clone();
                            return Err(ParseError {
                                message: format!("expected identifier after `.`, found `{}`", token_display(&cur)),
                                span: cur.span,
                                label: None, note: None, code: None,
                            });
                        }
                    }
                }
                TokenKind::LBracket => {
                    self.advance(); // [
                    if self.current().kind != TokenKind::RBracket {
                        if self.current().kind == TokenKind::Colon {
                            // slice [start:end]
                            self.advance();
                            if self.current().kind != TokenKind::RBracket {
                                self.parse_expr()?;
                            }
                        } else {
                            self.parse_expr()?;
                            if self.eat(&TokenKind::Colon) {
                                if self.current().kind != TokenKind::RBracket {
                                    self.parse_expr()?;
                                }
                            }
                        }
                    }
                    self.expect(&TokenKind::RBracket)?;
                }
                TokenKind::LParen => {
                    // Function call
                    self.advance(); // (
                    // Optional named args: { name: val, ... }
                    if self.current().kind == TokenKind::LBrace {
                        self.advance();
                        while !self.at_eof() && self.current().kind != TokenKind::RBrace {
                            let (_, _) = self.expect_identifier()?;
                            self.expect(&TokenKind::Colon)?;
                            self.parse_expr()?;
                            if !self.eat(&TokenKind::Comma) { break; }
                        }
                        self.eat(&TokenKind::RBrace);
                        self.expect(&TokenKind::RParen)?;
                    } else {
                        while !self.at_eof() && self.current().kind != TokenKind::RParen {
                            self.parse_expr()?;
                            if !self.eat(&TokenKind::Comma) { break; }
                        }
                        self.expect(&TokenKind::RParen)?;
                    }
                }
                _ => break,
            }
        }
        Ok(())
    }

    fn parse_primary(&mut self) -> Result<(), ParseError> {
        match self.current().kind.clone() {
            // Literals
            TokenKind::NumberLiteral(_) | TokenKind::StringLiteral(_) | 
            TokenKind::HexLiteral(_) | TokenKind::BoolLiteral(_) => {
                self.advance();
                // Handle unicode/hex/unicode string concatenation
                while matches!(self.current().kind, TokenKind::StringLiteral(_) | TokenKind::HexLiteral(_)) {
                    self.advance();
                }
            }
            // Identifiers
            TokenKind::Identifier(_) => {
                self.advance();
            }
            // Parenthesized expression or tuple
            TokenKind::LParen => {
                self.advance(); // (
                if self.current().kind == TokenKind::RParen {
                    self.advance();
                } else {
                    // Could be tuple assignment target or expression
                    self.parse_expr()?;
                    while self.eat(&TokenKind::Comma) {
                        if self.current().kind != TokenKind::RParen {
                            self.parse_expr()?;
                        }
                    }
                    self.expect(&TokenKind::RParen)?;
                }
            }
            // Type casts: uint256(x), address(x), etc.
            TokenKind::Address => {
                self.advance();
                if self.eat(&TokenKind::Payable) {
                    // address payable (...)
                }
                // Optional function call
            }
            TokenKind::Bool | TokenKind::String_ | TokenKind::Bytes |
            TokenKind::Bytes_(_) | TokenKind::Int(_) | TokenKind::Uint(_) => {
                self.advance();
                // type conversion cast or array construction
            }
            // new expression
            TokenKind::New => {
                self.advance();
                self.parse_type()?;
            }
            // type(...)
            TokenKind::Type => {
                self.advance();
                if self.current().kind == TokenKind::LParen {
                    self.skip_parens();
                }
            }
            // payable(...)
            TokenKind::Payable => {
                self.advance();
                if self.current().kind == TokenKind::LParen {
                    self.skip_parens();
                }
            }
            TokenKind::This | TokenKind::Super => {
                self.advance();
            }
            _ if is_keyword_usable_as_identifier(&self.current().kind) => {
                self.advance();
            }
            _ => {
                // Error - expected an expression
                let cur = self.current().clone();
                let possible = "`(`, `+`, `[`, `delete`, `new`, `payable`, `type`, elementary type name, identifier, or literal";
                return Err(ParseError {
                    message: format!("expected one of {}, found `{}`", possible, token_display(&cur)),
                    span: cur.span,
                    label: Some(format!("expected one of 10 possible tokens")),
                    note: None,
                    code: None,
                });
            }
        }
        Ok(())
    }

    fn skip_to_closing_paren(&mut self) -> Result<(), ParseError> {
        let mut depth = 1i32;
        loop {
            match self.current().kind {
                TokenKind::LParen => { depth += 1; self.advance(); }
                TokenKind::RParen => {
                    depth -= 1;
                    self.advance();
                    if depth == 0 { break; }
                }
                TokenKind::Eof => {
                    let cur = self.current().clone();
                    return Err(ParseError {
                        message: "unexpected end of file".to_string(),
                        span: cur.span,
                        label: None, note: None, code: None,
                    });
                }
                _ => { self.advance(); }
            }
        }
        Ok(())
    }
}

