# The first error is right but then there's cascading errors.
# The problem is when parse_block returns Err, the error propagates up through parse_function,
# which returns Err, which gets caught by parse_contract_item, which propagates to 
# parse_contract, then to parse_source_unit_item, which then continues to the next token.
# After the error, we're at ";" and "}" is skipped somehow.

# The issue is in recover_to_next_toplevel: it doesn't consume the "}" properly
# After an error in parse_function, the parser recovers and tries to parse more items.
# But the RBrace of the contract is consumed by skip_block or something.

# The original only shows 1 error here. Let me fix the error recovery.
# When we get an error in a function body, we should recover by skipping to the end of the function body
# and then continuing with contract items.

# The issue: parse_function returns Err, so parse_contract_item returns Err.
# But then recover_in_contract tries to find the next item.
# It looks for "}" which would be the end of contract, not end of function.

# Actually the REAL solution is: when parse_block errors, we should treat that as recoverable
# within the function parse, not propagate it as a fatal error.

# Let me change the approach: when parsing function bodies, collect errors but don't propagate
python3 -c "
with open('solar_impl/src/parser.rs', 'r') as f:
    content = f.read()

# Change parse_block to be called with error recovery
old_body2 = '''        let body = if self.current().kind == TokenKind::Semicolon {
            self.advance();
            None
        } else if self.current().kind == TokenKind::LBrace {
            self.parse_block()?;
            Some(())
        } else {
            None
        };'''

new_body2 = '''        let body = if self.current().kind == TokenKind::Semicolon {
            self.advance();
            None
        } else if self.current().kind == TokenKind::LBrace {
            // Parse block with error recovery - errors in function bodies
            // stop at first error and skip the rest of the block
            let block_start = self.pos;
            match self.parse_block() {
                Ok(()) => Some(()),
                Err(e) => {
                    self.errors.push(e);
                    // Recovery: skip to end of block
                    // We're now somewhere inside the block, need to skip rest
                    self.recover_block(block_start);
                    Some(())
                }
            }
        } else {
            None
        };'''

count = content.count(old_body2)
content = content.replace(old_body2, new_body2)
print(f'Replaced {count} occurrences')

with open('solar_impl/src/parser.rs', 'w') as f:
    f.write(content)
"

