impl<'a> Parser<'a> {
    /// Recover after an error in a block by finding the matching closing brace
    pub fn recover_block(&mut self, _block_start_pos: usize) {
        // Find the next RBrace at depth 0
        let mut depth = 0i32;
        loop {
            match self.current().kind {
                TokenKind::LBrace => { depth += 1; self.advance(); }
                TokenKind::RBrace => {
                    if depth == 0 {
                        self.advance(); // consume the }
                        break;
                    }
                    depth -= 1;
                    self.advance();
                }
                TokenKind::Eof => break,
                _ => { self.advance(); }
            }
        }
    }
}
EOF
